    AWSManagedRulesACFPRuleSet.add_member(:creation_path, Smithy::Schema::Shapes::ShapeRef.new(shape: CreationPathString, location_name: 'CreationPath', traits: {"smithy.api#documentation" => "<p>The path of the account creation endpoint for your application. This is the page on your website that accepts the completed registration form for a new user. This page must accept <code>POST</code> requests.</p>\n         <p>For example, for the URL <code>https://example.com/web/newaccount</code>, you would provide\n\tthe path <code>/web/newaccount</code>. Account creation page paths that\n\tstart with the path that you provide are considered a match. For example\n\t<code>/web/newaccount</code> matches the account creation paths\n\t\t<code>/web/newaccount</code>, <code>/web/newaccount/</code>,\n\t\t<code>/web/newaccountPage</code>, and\n\t\t<code>/web/newaccount/thisPage</code>, but doesn't match the path\n\t\t<code>/home/web/newaccount</code> or\n\t\t<code>/website/newaccount</code>. </p>", "smithy.api#required" => {}}))
    AWSManagedRulesACFPRuleSet.add_member(:registration_page_path, Smithy::Schema::Shapes::ShapeRef.new(shape: RegistrationPagePathString, location_name: 'RegistrationPagePath', traits: {"smithy.api#documentation" => "<p>The path of the account registration endpoint for your application. This is the page on your website that presents the registration form to new users. </p>\n         <note>\n            <p>This page must accept <code>GET</code> text/html requests.</p>\n         </note>\n         <p>For example, for the URL <code>https://example.com/web/registration</code>, you would provide\n\tthe path <code>/web/registration</code>. Registration page paths that\n\tstart with the path that you provide are considered a match. For example\n\t    <code>/web/registration</code> matches the registration paths\n\t    <code>/web/registration</code>, <code>/web/registration/</code>,\n\t    <code>/web/registrationPage</code>, and\n\t    <code>/web/registration/thisPage</code>, but doesn't match the path\n\t    <code>/home/web/registration</code> or\n\t    <code>/website/registration</code>. </p>", "smithy.api#required" => {}}))
    AWSManagedRulesACFPRuleSet.add_member(:request_inspection, Smithy::Schema::Shapes::ShapeRef.new(shape: RequestInspectionACFP, location_name: 'RequestInspection', traits: {"smithy.api#documentation" => "<p>The criteria for inspecting account creation requests, used by the ACFP rule group to validate and track account creation attempts.  </p>", "smithy.api#required" => {}}))
    AWSManagedRulesACFPRuleSet.add_member(:response_inspection, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspection, location_name: 'ResponseInspection', traits: {"smithy.api#documentation" => "<p>The criteria for inspecting responses to account creation requests, used by the ACFP rule group to track account creation success rates. </p>\n         <note>\n            <p>Response inspection is available only in web ACLs that protect Amazon CloudFront distributions.</p>\n         </note>\n         <p>The ACFP rule group evaluates the responses that your protected resources send back to client account creation attempts, keeping count of successful and failed attempts from each IP address and client session. Using this information, the rule group labels \n               and mitigates requests from client sessions and IP addresses that have had too many successful account creation attempts in a short amount of time. </p>"}))
    AWSManagedRulesACFPRuleSet.add_member(:enable_regex_in_path, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableRegexInPath', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Allow the use of regular expressions in the registration page path and the account creation path. </p>"}))
    AWSManagedRulesACFPRuleSet.type = Types::AWSManagedRulesACFPRuleSet
    AWSManagedRulesATPRuleSet.add_member(:login_path, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'LoginPath', traits: {"smithy.api#documentation" => "<p>The path of the login endpoint for your application. For example, for the URL\n            <code>https://example.com/web/login</code>, you would provide the path\n            <code>/web/login</code>. Login paths that start with the path that you provide are considered a match. For example <code>/web/login</code> matches the login paths <code>/web/login</code>, <code>/web/login/</code>, <code>/web/loginPage</code>, and <code>/web/login/thisPage</code>, but doesn't match the login path <code>/home/web/login</code> or <code>/website/login</code>.</p>\n         <p>The rule group inspects only HTTP <code>POST</code> requests to your specified login endpoint.</p>", "smithy.api#required" => {}}))
    AWSManagedRulesATPRuleSet.add_member(:request_inspection, Smithy::Schema::Shapes::ShapeRef.new(shape: RequestInspection, location_name: 'RequestInspection', traits: {"smithy.api#documentation" => "<p>The criteria for inspecting login requests, used by the ATP rule group to validate credentials usage.  </p>"}))
    AWSManagedRulesATPRuleSet.add_member(:response_inspection, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspection, location_name: 'ResponseInspection', traits: {"smithy.api#documentation" => "<p>The criteria for inspecting responses to login requests, used by the ATP rule group to track login failure rates. </p>\n         <note>\n            <p>Response inspection is available only in web ACLs that protect Amazon CloudFront distributions.</p>\n         </note>\n         <p>The ATP rule group evaluates the responses that your protected resources send back to client login attempts, keeping count of successful and failed attempts for each IP address and client session. Using this information, the rule group labels \n               and mitigates requests from client sessions and IP addresses that have had too many failed login attempts in a short amount of time. </p>"}))
    AWSManagedRulesATPRuleSet.add_member(:enable_regex_in_path, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableRegexInPath', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Allow the use of regular expressions in the login page path. </p>"}))
    AWSManagedRulesATPRuleSet.type = Types::AWSManagedRulesATPRuleSet
    AWSManagedRulesAntiDDoSRuleSet.add_member(:client_side_action_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ClientSideActionConfig, location_name: 'ClientSideActionConfig', traits: {"smithy.api#documentation" => "<p>Configures the request handling that's applied by the managed rule group rules <code>ChallengeAllDuringEvent</code> and <code>ChallengeDDoSRequests</code> during a distributed denial of service (DDoS) attack.</p>", "smithy.api#required" => {}}))
    AWSManagedRulesAntiDDoSRuleSet.add_member(:sensitivity_to_block, Smithy::Schema::Shapes::ShapeRef.new(shape: SensitivityToAct, location_name: 'SensitivityToBlock', traits: {"smithy.api#documentation" => "<p>The sensitivity that the rule group rule <code>DDoSRequests</code> uses when matching against the \n           DDoS suspicion labeling on a request. The managed rule group adds the labeling during DDoS events, before the <code>DDoSRequests</code> rule runs. \n       </p>\n         <p>The higher the sensitivity, the more levels of labeling that the rule matches: </p>\n         <ul>\n            <li>\n               <p>Low sensitivity is less sensitive, causing the rule to match only on the most likely participants in an attack, which are the requests with the high suspicion label <code>awswaf:managed:aws:anti-ddos:high-suspicion-ddos-request</code>.</p>\n            </li>\n            <li>\n               <p>Medium sensitivity causes the rule to match on the medium and high suspicion labels.</p>\n            </li>\n            <li>\n               <p>High sensitivity causes the rule to match on all of the suspicion labels: low, medium, and high.</p>\n            </li>\n         </ul>\n         <p>Default: <code>LOW</code>\n         </p>"}))
    AWSManagedRulesAntiDDoSRuleSet.type = Types::AWSManagedRulesAntiDDoSRuleSet
    AWSManagedRulesBotControlRuleSet.add_member(:inspection_level, Smithy::Schema::Shapes::ShapeRef.new(shape: InspectionLevel, location_name: 'InspectionLevel', traits: {"smithy.api#documentation" => "<p>The inspection level to use for the Bot Control rule group. The common level is the least expensive. The \n           targeted level includes all common level rules and adds rules with more advanced inspection criteria. For \n   details, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/aws-managed-rule-groups-bot.html\">WAF Bot Control rule group</a>\n               in the <i>WAF Developer Guide</i>.</p>", "smithy.api#required" => {}}))
    AWSManagedRulesBotControlRuleSet.add_member(:enable_machine_learning, Smithy::Schema::Shapes::ShapeRef.new(shape: EnableMachineLearning, location_name: 'EnableMachineLearning', traits: {"smithy.api#default" => true, "smithy.api#documentation" => "<p>Applies only to the targeted inspection level. </p>\n         <p>Determines whether to use machine learning (ML) to\n      analyze your web traffic for bot-related activity. Machine learning is required for the Bot Control rules <code>TGT_ML_CoordinatedActivityLow</code> and <code>TGT_ML_CoordinatedActivityMedium</code>, which\ninspect for anomalous behavior that might indicate distributed, coordinated bot activity.</p>\n         <p>For more information about this choice, see the listing for these rules in the table at <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/aws-managed-rule-groups-bot.html#aws-managed-rule-groups-bot-rules\">Bot Control rules listing</a> in the\n            <i>WAF Developer Guide</i>.</p>\n         <p>Default: <code>TRUE</code>\n         </p>"}))
    AWSManagedRulesBotControlRuleSet.type = Types::AWSManagedRulesBotControlRuleSet
    ActionCondition.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: ActionValue, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The action setting that a log record must contain in order to meet the condition. This is the action that WAF applied to the web request. </p>\n         <p>For rule groups, this is either the configured rule action setting, or if you've applied a rule action override to the rule, it's the override action. \n       The value <code>EXCLUDED_AS_COUNT</code> matches on \n       excluded rules and also on rules that have a rule action override of Count. </p>", "smithy.api#required" => {}}))
