    AsnMatchStatement.add_member(:forwarded_ip_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ForwardedIPConfig, location_name: 'ForwardedIPConfig', traits: {"smithy.api#documentation" => "<p>The configuration for inspecting IP addresses to match against an ASN in an HTTP header that you specify, \n         instead of using the IP address that's reported by the web request origin. Commonly, this is the X-Forwarded-For (XFF) header, \n         but you can specify any header name. </p>"}))
