    AssociatedResourceType.add_member(:cloudfront, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CLOUDFRONT', traits: {"smithy.api#enumValue" => "CLOUDFRONT"}))
    AssociatedResourceType.add_member(:api_gateway, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'API_GATEWAY', traits: {"smithy.api#enumValue" => "API_GATEWAY"}))
    AssociatedResourceType.add_member(:cognito_user_pool, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'COGNITO_USER_POOL', traits: {"smithy.api#enumValue" => "COGNITO_USER_POOL"}))
