    CaptchaConfig.type = Types::CaptchaConfig
    CaptchaResponse.add_member(:response_code, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseCode, location_name: 'ResponseCode', traits: {"smithy.api#documentation" => "<p>The HTTP response code indicating the status of the <code>CAPTCHA</code> token in the\n         web request. If the token is missing, invalid, or expired, this code is <code>405 Method\n            Not Allowed</code>.</p>"}))
