    CaptchaResponse.type = Types::CaptchaResponse
    ChallengeAction.add_member(:custom_request_handling, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomRequestHandling, location_name: 'CustomRequestHandling', traits: {"smithy.api#documentation" => "<p>Defines custom handling for the web request, used when the challenge inspection determines that the request's token is valid and unexpired.</p>\n         <p>For information about customizing web requests and responses, \n           see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-custom-request-response.html\">Customizing web requests and responses in WAF</a> \n    in the <i>WAF Developer Guide</i>. </p>"}))
