    Condition.add_member(:label_name_condition, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelNameCondition, location_name: 'LabelNameCondition', traits: {"smithy.api#documentation" => "<p>A single label name condition. This is the fully qualified label name that a log record must contain in order to meet the condition. \n       Fully qualified labels have a prefix, optional namespaces, and label name. The prefix identifies the rule group or web ACL context of the rule that added the label.  </p>"}))
