    CreateRuleGroupRequest.add_member(:capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityUnit, location_name: 'Capacity', traits: {"smithy.api#documentation" => "<p>The web ACL capacity units (WCUs) required for this rule group.</p>\n         <p>When you create your own rule group, you define this, and you cannot change it after creation. \n          When you add or modify the rules in a rule group, WAF enforces this limit. You can check the capacity \n          for a set of rules using <a>CheckCapacity</a>.</p>\n         <p>WAF uses WCUs to calculate and control the operating\n         resources that are used to run your rules, rule groups, and web ACLs. WAF\n         calculates capacity differently for each rule type, to reflect the relative cost of each rule. \n         Simple rules that cost little to run use fewer WCUs than more complex rules\n\t\t\t\tthat use more processing power. \n\t\t\t\tRule group capacity is fixed at creation, which helps users plan their  \n         web ACL WCU usage when they use a rule group. For more information, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/aws-waf-capacity-units.html\">WAF web ACL capacity units (WCU)</a> \n    in the <i>WAF Developer Guide</i>. </p>", "smithy.api#required" => {}}))
    CreateRuleGroupRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the rule group that helps with identification. </p>"}))
    CreateRuleGroupRequest.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: Rules, location_name: 'Rules', traits: {"smithy.api#documentation" => "<p>The <a>Rule</a> statements used to identify the web requests that you \n         want to manage. Each rule includes one top-level statement that WAF uses to identify matching  \n         web requests, and parameters that govern how WAF handles them. \n      </p>"}))
