    CreateRuleGroupRequest.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>An array of key:value pairs to associate with the resource.</p>"}))
    CreateRuleGroupRequest.add_member(:custom_response_bodies, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomResponseBodies, location_name: 'CustomResponseBodies', traits: {"smithy.api#documentation" => "<p>A map of custom response keys and content bodies. When you create a rule with a block action, you can send a custom response to the web request. You define these for the rule group, and then use them in the rules that you define in the rule group. </p>\n         <p>For information about customizing web requests and responses, \n           see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-custom-request-response.html\">Customizing web requests and responses in WAF</a> \n    in the <i>WAF Developer Guide</i>. </p>\n         <p>For information about the limits on count and size for custom request and response settings, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/limits.html\">WAF quotas</a> \n     in the <i>WAF Developer Guide</i>. </p>"}))
