    CustomHTTPHeader.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomHTTPHeaderName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the custom header. </p>\n         <p>For custom request header insertion, when WAF inserts the header into the request,\n         it prefixes this name <code>x-amzn-waf-</code>, to avoid confusion with the headers that\n         are already in the request. For example, for the header name <code>sample</code>, WAF\n         inserts the header <code>x-amzn-waf-sample</code>.</p>", "smithy.api#required" => {}}))
