    DataProtection.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: DataProtectionAction, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>Specifies how to protect the field. WAF can apply a one-way hash to the field or hard code a string substitution. </p>\n         <ul>\n            <li>\n               <p>One-way hash example: <code>ade099751dEXAMPLEHASH2ea9f3393f80dd5d3bEXAMPLEHASH966ae0d3cd5a1e</code>\n               </p>\n            </li>\n            <li>\n               <p>Substitution example: <code>REDACTED</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    DataProtection.add_member(:exclude_rule_match_details, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ExcludeRuleMatchDetails', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether to also exclude any rule match details from the data protection you have enabled for a given field.  WAF logs these details for non-terminating \n           matching rules and for the terminating matching rule. For additional information, see \n            <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/logging-fields.html\">Log fields for web ACL traffic</a> in the\n            <i>WAF Developer Guide</i>.</p>\n         <p>Default: <code>FALSE</code>\n         </p>"}))
    DataProtection.add_member(:exclude_rate_based_details, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ExcludeRateBasedDetails', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether to also exclude any rate-based rule details from the data protection you have enabled for a given field. If you specify this exception, RateBasedDetails will show the value of the field. \n           For additional information, see the log field <code>rateBasedRuleList</code> at \n            <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/logging-fields.html\">Log fields for web ACL traffic</a> in the\n            <i>WAF Developer Guide</i>.</p>\n         <p>Default: <code>FALSE</code>\n         </p>"}))
