    DataProtectionAction.add_member(:hash, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HASH', traits: {"smithy.api#enumValue" => "HASH"}))
