    DescribeManagedRuleGroupResponse.add_member(:sns_topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'SnsTopicArn', traits: {"smithy.api#documentation" => "<p>The Amazon resource name (ARN) of the Amazon Simple Notification Service SNS topic that's used to provide notification of changes\n         to the managed rule group. You can subscribe to the SNS topic to receive notifications when\n         the managed rule group is modified, such as for new versions and for version expiration.\n         For more information, see the <a href=\"https://docs.aws.amazon.com/sns/latest/dg/welcome.html\">Amazon Simple Notification Service Developer Guide</a>.</p>"}))
    DescribeManagedRuleGroupResponse.add_member(:capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityUnit, location_name: 'Capacity', traits: {"smithy.api#documentation" => "<p>The web ACL capacity units (WCUs) required for this rule group.</p>\n         <p>WAF uses WCUs to calculate and control the operating\n         resources that are used to run your rules, rule groups, and web ACLs. WAF\n         calculates capacity differently for each rule type, to reflect the relative cost of each rule. \n         Simple rules that cost little to run use fewer WCUs than more complex rules\n\t\t\t\tthat use more processing power. \n\t\t\t\tRule group capacity is fixed at creation, which helps users plan their  \n         web ACL WCU usage when they use a rule group. For more information, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/aws-waf-capacity-units.html\">WAF web ACL capacity units (WCU)</a> \n    in the <i>WAF Developer Guide</i>. </p>"}))
    DescribeManagedRuleGroupResponse.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleSummaries, location_name: 'Rules', traits: {"smithy.api#documentation" => "<p></p>"}))
    DescribeManagedRuleGroupResponse.add_member(:label_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelName, location_name: 'LabelNamespace', traits: {"smithy.api#documentation" => "<p>The label namespace prefix for this rule group. All labels added by rules in this rule group have this prefix. </p>\n         <ul>\n            <li>\n               <p>The syntax for the label namespace prefix for a managed rule group is the following: </p>\n               <p>\n                  <code>awswaf:managed:<vendor>:<rule group name></code>:</p>\n            </li>\n            <li>\n               <p>When a rule with a label matches a web request, WAF adds the fully qualified label to the request. A fully qualified label is made up of the label namespace from the rule group or web ACL where the rule is defined and the label from the rule, separated by a colon: </p>\n               <p>\n                  <code><label namespace>:<label from rule></code>\n               </p>\n            </li>\n         </ul>"}))
    DescribeManagedRuleGroupResponse.add_member(:available_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelSummaries, location_name: 'AvailableLabels', traits: {"smithy.api#documentation" => "<p>The labels that one or more rules in this rule group add to matching web requests. These labels are defined in the <code>RuleLabels</code> for a <a>Rule</a>.</p>"}))
    DescribeManagedRuleGroupResponse.add_member(:consumed_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelSummaries, location_name: 'ConsumedLabels', traits: {"smithy.api#documentation" => "<p>The labels that one or more rules in this rule group match against in label match statements. These labels are defined in a <code>LabelMatchStatement</code> specification, in the <a>Statement</a> definition of a rule.  </p>"}))
