    FieldToMatch.add_member(:single_header, Smithy::Schema::Shapes::ShapeRef.new(shape: SingleHeader, location_name: 'SingleHeader', traits: {"smithy.api#documentation" => "<p>Inspect a single header. Provide the name of the header to inspect, for example,\n            <code>User-Agent</code> or <code>Referer</code>. This setting isn't case\n         sensitive.</p>\n         <p>Example JSON: <code>\"SingleHeader\": { \"Name\": \"haystack\" }</code>\n         </p>\n         <p>Alternately, you can filter and inspect all headers with the <code>Headers</code>\n            <code>FieldToMatch</code> setting. </p>"}))
