    FirewallManagerRuleGroup.add_member(:firewall_manager_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: FirewallManagerStatement, location_name: 'FirewallManagerStatement', traits: {"smithy.api#documentation" => "<p>The processing guidance for an Firewall Manager rule. This is like a regular rule <a>Statement</a>, but it can only contain a rule group reference.</p>", "smithy.api#required" => {}}))
    FirewallManagerRuleGroup.add_member(:override_action, Smithy::Schema::Shapes::ShapeRef.new(shape: OverrideAction, location_name: 'OverrideAction', traits: {"smithy.api#documentation" => "<p>The action to use in the place of the action that results from the rule group evaluation. Set the override action to none to leave the result of the rule group alone. Set it to count to override the result to count only. </p>\n         <p>You can only use this for rule statements that reference a rule group, like <code>RuleGroupReferenceStatement</code> and <code>ManagedRuleGroupStatement</code>. </p>\n         <note>\n            <p>This option is usually set to none. It does not affect how the rules in the rule group are evaluated. If you want the rules in the rule group to only count  \n  matches, do not use this and instead use the rule action override option, with <code>Count</code> action, in your rule group reference statement settings. </p>\n         </note>", "smithy.api#required" => {}}))
