    HTTPRequest.add_member(:uri, Smithy::Schema::Shapes::ShapeRef.new(shape: URIString, location_name: 'URI', traits: {"smithy.api#documentation" => "<p>The URI path of the request, which identifies the resource, for example,\n            <code>/images/daily-ad.jpg</code>.</p>"}))
    HTTPRequest.add_member(:method, Smithy::Schema::Shapes::ShapeRef.new(shape: HTTPMethod, location_name: 'Method', traits: {"smithy.api#documentation" => "<p>The HTTP method specified in the sampled web request. </p>"}))
