    HTTPRequest.add_member(:headers, Smithy::Schema::Shapes::ShapeRef.new(shape: HTTPHeaders, location_name: 'Headers', traits: {"smithy.api#documentation" => "<p>A complex type that contains the name and value for each header in the sampled web\n         request.</p>"}))
    HTTPRequest.type = Types::HTTPRequest
    HeaderMatchPattern.add_member(:all, Smithy::Schema::Shapes::ShapeRef.new(shape: All, location_name: 'All', traits: {"smithy.api#documentation" => "<p>Inspect all headers. </p>"}))
    HeaderMatchPattern.add_member(:included_headers, Smithy::Schema::Shapes::ShapeRef.new(shape: HeaderNames, location_name: 'IncludedHeaders', traits: {"smithy.api#documentation" => "<p>Inspect only the headers that have a key that matches one of the strings specified here.\n      </p>"}))
    HeaderMatchPattern.add_member(:excluded_headers, Smithy::Schema::Shapes::ShapeRef.new(shape: HeaderNames, location_name: 'ExcludedHeaders', traits: {"smithy.api#documentation" => "<p>Inspect only the headers whose keys don't match any of the strings specified here.\n      </p>"}))
