    HeaderOrder.add_member(:oversize_handling, Smithy::Schema::Shapes::ShapeRef.new(shape: OversizeHandling, location_name: 'OversizeHandling', traits: {"smithy.api#documentation" => "<p>What WAF should do if the headers determined by your match scope are more numerous or larger than WAF can inspect. \n    WAF does not support inspecting the entire contents of request headers \n      when they exceed 8 KB (8192 bytes) or 200 total headers. The underlying host service forwards a maximum of 200 headers\n      and at most 8 KB of header contents to WAF. </p>\n         <p>The options for oversize handling are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CONTINUE</code> - Inspect the available headers normally, according to the rule inspection criteria. </p>\n            </li>\n            <li>\n               <p>\n                  <code>MATCH</code> - Treat the web request as matching the rule statement. WAF\n               applies the rule action to the request.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NO_MATCH</code> - Treat the web request as not matching the rule\n               statement.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    HeaderOrder.type = Types::HeaderOrder
    Headers.add_member(:match_pattern, Smithy::Schema::Shapes::ShapeRef.new(shape: HeaderMatchPattern, location_name: 'MatchPattern', traits: {"smithy.api#documentation" => "<p>The filter to use to identify the subset of headers to inspect in a web request. </p>\n         <p>You must specify exactly one setting: either <code>All</code>, <code>IncludedHeaders</code>, or <code>ExcludedHeaders</code>.</p>\n         <p>Example JSON: <code>\"MatchPattern\": { \"ExcludedHeaders\": [ \"KeyToExclude1\", \"KeyToExclude2\" ] }</code>\n         </p>", "smithy.api#required" => {}}))
    Headers.add_member(:match_scope, Smithy::Schema::Shapes::ShapeRef.new(shape: MapMatchScope, location_name: 'MatchScope', traits: {"smithy.api#documentation" => "<p>The parts of the headers to match with the rule inspection criteria. If you specify\n            <code>ALL</code>, WAF inspects both keys and values. </p>\n         <p>\n            <code>All</code> does not require a match to be found in the keys\n and a match to be found in the values. It requires a match to be found in the keys \n or the values or both. To require a match in the keys and in the values, use a logical <code>AND</code> statement\n to combine two match rules, one that inspects the keys and another that inspects the values. </p>", "smithy.api#required" => {}}))
    Headers.add_member(:oversize_handling, Smithy::Schema::Shapes::ShapeRef.new(shape: OversizeHandling, location_name: 'OversizeHandling', traits: {"smithy.api#documentation" => "<p>What WAF should do if the headers determined by your match scope are more numerous or larger than WAF can inspect. \n    WAF does not support inspecting the entire contents of request headers \n      when they exceed 8 KB (8192 bytes) or 200 total headers. The underlying host service forwards a maximum of 200 headers\n      and at most 8 KB of header contents to WAF. </p>\n         <p>The options for oversize handling are the following:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>CONTINUE</code> - Inspect the available headers normally, according to the rule inspection criteria. </p>\n            </li>\n            <li>\n               <p>\n                  <code>MATCH</code> - Treat the web request as matching the rule statement. WAF\n               applies the rule action to the request.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NO_MATCH</code> - Treat the web request as not matching the rule\n               statement.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    Headers.type = Types::Headers
    IPAddressVersion.add_member(:ipv4, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'IPV4', traits: {"smithy.api#enumValue" => "IPV4"}))
    IPAddressVersion.add_member(:ipv6, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'IPV6', traits: {"smithy.api#enumValue" => "IPV6"}))
