    IPSet.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>A unique identifier for the set. This ID is returned in the responses to create and list commands. You provide it to operations like update and delete.</p>", "smithy.api#required" => {}}))
    IPSet.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the entity.</p>", "smithy.api#required" => {}}))
    IPSet.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the IP set that helps with identification. </p>"}))
    IPSet.add_member(:ip_address_version, Smithy::Schema::Shapes::ShapeRef.new(shape: IPAddressVersion, location_name: 'IPAddressVersion', traits: {"smithy.api#documentation" => "<p>The version of the IP addresses, either <code>IPV4</code> or <code>IPV6</code>. </p>", "smithy.api#required" => {}}))
    IPSet.add_member(:addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: IPAddresses, location_name: 'Addresses', traits: {"smithy.api#documentation" => "<p>Contains an array of strings that specifies zero or more IP addresses or blocks of IP addresses that you want WAF to inspect for in incoming requests. All addresses must be specified using Classless Inter-Domain Routing (CIDR) notation. WAF supports all IPv4 and IPv6 CIDR ranges except for <code>/0</code>. </p>\n         <p>Example address strings: </p>\n         <ul>\n            <li>\n               <p>For requests that originated from the IP address 192.0.2.44, specify <code>192.0.2.44/32</code>.</p>\n            </li>\n            <li>\n               <p>For requests that originated from IP addresses from 192.0.2.0 to 192.0.2.255, specify \n               <code>192.0.2.0/24</code>.</p>\n            </li>\n            <li>\n               <p>For requests that originated from the IP address 1111:0000:0000:0000:0000:0000:0000:0111, specify <code>1111:0000:0000:0000:0000:0000:0000:0111/128</code>.</p>\n            </li>\n            <li>\n               <p>For requests that originated from IP addresses 1111:0000:0000:0000:0000:0000:0000:0000 to 1111:0000:0000:0000:ffff:ffff:ffff:ffff, specify <code>1111:0000:0000:0000:0000:0000:0000:0000/64</code>.</p>\n            </li>\n         </ul>\n         <p>For more information about CIDR notation, see the Wikipedia entry <a href=\"https://en.wikipedia.org/wiki/Classless_Inter-Domain_Routing\">Classless Inter-Domain Routing</a>.</p>\n         <p>Example JSON <code>Addresses</code> specifications: </p>\n         <ul>\n            <li>\n               <p>Empty array: <code>\"Addresses\": []</code>\n               </p>\n            </li>\n            <li>\n               <p>Array with one address: <code>\"Addresses\": [\"192.0.2.44/32\"]</code>\n               </p>\n            </li>\n            <li>\n               <p>Array with three addresses: <code>\"Addresses\": [\"192.0.2.44/32\", \"192.0.2.0/24\", \"192.0.0.0/16\"]</code>\n               </p>\n            </li>\n            <li>\n               <p>INVALID specification: <code>\"Addresses\": [\"\"]</code> INVALID </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    IPSet.type = Types::IPSet
    IPSetForwardedIPConfig.add_member(:header_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ForwardedIPHeaderName, location_name: 'HeaderName', traits: {"smithy.api#documentation" => "<p>The name of the HTTP header to use for the IP address. For example, to use the X-Forwarded-For (XFF) header, set this to <code>X-Forwarded-For</code>.</p>\n         <note>\n            <p>If the specified header isn't present in the request, WAF doesn't apply the rule to the web request at all.</p>\n         </note>", "smithy.api#required" => {}}))
    IPSetForwardedIPConfig.add_member(:fallback_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: FallbackBehavior, location_name: 'FallbackBehavior', traits: {"smithy.api#documentation" => "<p>The match status to assign to the web request if the request doesn't have a valid IP address in the specified position.</p>\n         <note>\n            <p>If the specified header isn't present in the request, WAF doesn't apply the rule to the web request at all.</p>\n         </note>\n         <p>You can specify the following fallback behaviors:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>MATCH</code> - Treat the web request as matching the rule statement. WAF applies the rule action to the request.</p>\n            </li>\n            <li>\n               <p>\n                  <code>NO_MATCH</code> - Treat the web request as not matching the rule statement.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    IPSetForwardedIPConfig.add_member(:position, Smithy::Schema::Shapes::ShapeRef.new(shape: ForwardedIPPosition, location_name: 'Position', traits: {"smithy.api#documentation" => "<p>The position in the header to search for the IP address. The header can contain IP\n         addresses of the original client and also of proxies. For example, the header value could\n         be <code>10.1.1.1, 127.0.0.0, 10.10.10.10</code> where the first IP address identifies the\n         original client and the rest identify proxies that the request went through. </p>\n         <p>The options for this setting are the following: </p>\n         <ul>\n            <li>\n               <p>FIRST - Inspect the first IP address in the list of IP addresses in the\n               header. This is usually the client's original IP.</p>\n            </li>\n            <li>\n               <p>LAST - Inspect the last IP address in the list of IP addresses in the\n               header.</p>\n            </li>\n            <li>\n               <p>ANY - Inspect all IP addresses in the header for a match. If the header\n               contains more than 10 IP addresses, WAF inspects the last 10.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    IPSetForwardedIPConfig.type = Types::IPSetForwardedIPConfig
    IPSetReferenceStatement.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the <a>IPSet</a> that this statement\n         references.</p>", "smithy.api#required" => {}}))
    IPSetReferenceStatement.add_member(:ip_set_forwarded_ip_config, Smithy::Schema::Shapes::ShapeRef.new(shape: IPSetForwardedIPConfig, location_name: 'IPSetForwardedIPConfig', traits: {"smithy.api#documentation" => "<p>The configuration for inspecting IP addresses in an HTTP header that you specify, instead of using the IP address that's reported by the web request origin. Commonly, this is the X-Forwarded-For (XFF) header, but you can specify any header name. </p>\n         <note>\n            <p>If the specified header isn't present in the request, WAF doesn't apply the rule to the web request at all.</p>\n         </note>"}))
    IPSetReferenceStatement.type = Types::IPSetReferenceStatement
    IPSetSummaries.member = Smithy::Schema::Shapes::ShapeRef.new(shape: IPSetSummary)
    IPSetSummary.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the IP set. You cannot change the name of an <code>IPSet</code> after you create it.</p>"}))
    IPSetSummary.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>A unique identifier for the set. This ID is returned in the responses to create and list commands. You provide it to operations like update and delete.</p>"}))
    IPSetSummary.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the IP set that helps with identification. </p>"}))
    IPSetSummary.add_member(:lock_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LockToken, location_name: 'LockToken', traits: {"smithy.api#documentation" => "<p>A token used for optimistic locking. WAF returns a token to your <code>get</code> and <code>list</code> requests, to mark the state of the entity at the time of the request. To make changes to the entity associated with the token, you provide the token to operations like <code>update</code> and <code>delete</code>. WAF uses the token to ensure that no changes have been made to the entity since you last retrieved it. If a change has been made, the update fails with a <code>WAFOptimisticLockException</code>. If this happens, perform another <code>get</code>, and use the new token returned by that operation. </p>"}))
    IPSetSummary.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the entity.</p>"}))
    IPSetSummary.type = Types::IPSetSummary
    ImmunityTimeProperty.add_member(:immunity_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeWindowSecond, location_name: 'ImmunityTime', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, that a <code>CAPTCHA</code> or challenge timestamp is considered valid by WAF. The default\n          setting is 300. </p>\n         <p>For the Challenge action, the minimum setting is 300. </p>", "smithy.api#required" => {}}))
    ImmunityTimeProperty.type = Types::ImmunityTimeProperty
