    Label.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The label string. </p>", "smithy.api#required" => {}}))
    Label.type = Types::Label
    LabelMatchScope.add_member(:label, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LABEL', traits: {"smithy.api#enumValue" => "LABEL"}))
    LabelMatchScope.add_member(:namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'NAMESPACE', traits: {"smithy.api#enumValue" => "NAMESPACE"}))
