    ManagedProductDescriptor.add_member(:managed_rule_set_name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'ManagedRuleSetName', traits: {"smithy.api#documentation" => "<p>The name of the managed rule group. For example, <code>AWSManagedRulesAnonymousIpList</code> or <code>AWSManagedRulesATPRuleSet</code>.</p>"}))
    ManagedProductDescriptor.add_member(:product_id, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductId, location_name: 'ProductId', traits: {"smithy.api#documentation" => "<p>A unique identifier for the rule group. This ID is returned in the responses to create and list commands. You provide it to operations like update and delete.</p>"}))
    ManagedProductDescriptor.add_member(:product_link, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductLink, location_name: 'ProductLink', traits: {"smithy.api#documentation" => "<p>For Amazon Web Services Marketplace managed rule groups only, the link to the rule group product page. </p>"}))
    ManagedProductDescriptor.add_member(:product_title, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductTitle, location_name: 'ProductTitle', traits: {"smithy.api#documentation" => "<p>The display name for the managed rule group. For example, <code>Anonymous IP list</code> or <code>Account takeover prevention</code>.</p>"}))
    ManagedProductDescriptor.add_member(:product_description, Smithy::Schema::Shapes::ShapeRef.new(shape: ProductDescription, location_name: 'ProductDescription', traits: {"smithy.api#documentation" => "<p>A short description of the managed rule group.</p>"}))
    ManagedProductDescriptor.add_member(:sns_topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'SnsTopicArn', traits: {"smithy.api#documentation" => "<p>The Amazon resource name (ARN) of the Amazon Simple Notification Service SNS topic that's used to provide notification of changes\n         to the managed rule group. You can subscribe to the SNS topic to receive notifications when\n         the managed rule group is modified, such as for new versions and for version expiration.\n         For more information, see the <a href=\"https://docs.aws.amazon.com/sns/latest/dg/welcome.html\">Amazon Simple Notification Service Developer Guide</a>.</p>"}))
    ManagedProductDescriptor.add_member(:is_versioning_supported, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IsVersioningSupported', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether the rule group is versioned. </p>"}))
    ManagedProductDescriptor.add_member(:is_advanced_managed_rule_set, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'IsAdvancedManagedRuleSet', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether the rule group provides an advanced set of protections, such as the the Amazon Web Services Managed Rules rule groups that \n           are used for WAF intelligent threat mitigation.  </p>"}))
