    OnSourceDDoSProtectionConfig.add_member(:alb_low_reputation_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: LowReputationMode, location_name: 'ALBLowReputationMode', traits: {"smithy.api#documentation" => "<p>The level of DDoS protection that applies to web ACLs associated with Application Load Balancers. <code>ACTIVE_UNDER_DDOS</code> protection is enabled by default whenever a web ACL is associated with an Application Load Balancer. \n         In the event that an Application Load Balancer experiences high-load conditions or suspected DDoS attacks, the <code>ACTIVE_UNDER_DDOS</code> protection automatically rate limits traffic from known low reputation sources without disrupting Application Load Balancer availability. \n      <code>ALWAYS_ON</code> protection provides constant, always-on monitoring of known low reputation sources for suspected DDoS attacks. While this provides a higher level of protection, there may be potential impacts on legitimate traffic.</p>", "smithy.api#required" => {}}))
