    PutManagedRuleSetVersionsRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the managed rule set. You use this, along with the rule set ID, to identify the rule set.</p>\n         <p>This name is assigned to the corresponding managed rule group, which your customers can access and use. </p>", "smithy.api#required" => {}}))
    PutManagedRuleSetVersionsRequest.add_member(:scope, Smithy::Schema::Shapes::ShapeRef.new(shape: Scope, location_name: 'Scope', traits: {"smithy.api#documentation" => "<p>Specifies whether this is for a global resource type, such as a Amazon CloudFront distribution. For an Amplify application, use <code>CLOUDFRONT</code>.</p>\n         <p>To work with CloudFront, you must also specify the Region US East (N. Virginia) as follows: </p>\n         <ul>\n            <li>\n               <p>CLI - Specify the Region when you use the CloudFront scope: <code>--scope=CLOUDFRONT --region=us-east-1</code>. </p>\n            </li>\n            <li>\n               <p>API and SDKs - For all calls, use the Region endpoint us-east-1. </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    PutManagedRuleSetVersionsRequest.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>A unique identifier for the managed rule set. The ID is returned in the responses to commands like <code>list</code>. You provide it to operations like <code>get</code> and <code>update</code>.</p>", "smithy.api#required" => {}}))
    PutManagedRuleSetVersionsRequest.add_member(:lock_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LockToken, location_name: 'LockToken', traits: {"smithy.api#documentation" => "<p>A token used for optimistic locking. WAF returns a token to your <code>get</code> and <code>list</code> requests, to mark the state of the entity at the time of the request. To make changes to the entity associated with the token, you provide the token to operations like <code>update</code> and <code>delete</code>. WAF uses the token to ensure that no changes have been made to the entity since you last retrieved it. If a change has been made, the update fails with a <code>WAFOptimisticLockException</code>. If this happens, perform another <code>get</code>, and use the new token returned by that operation. </p>", "smithy.api#required" => {}}))
    PutManagedRuleSetVersionsRequest.add_member(:recommended_version, Smithy::Schema::Shapes::ShapeRef.new(shape: VersionKeyString, location_name: 'RecommendedVersion', traits: {"smithy.api#documentation" => "<p>The version of the named managed rule group that you'd like your customers to choose,\n         from among your version offerings. </p>"}))
    PutManagedRuleSetVersionsRequest.add_member(:versions_to_publish, Smithy::Schema::Shapes::ShapeRef.new(shape: VersionsToPublish, location_name: 'VersionsToPublish', traits: {"smithy.api#documentation" => "<p>The versions of the named managed rule group that you want to offer to your customers.\n      </p>"}))
    PutManagedRuleSetVersionsRequest.type = Types::PutManagedRuleSetVersionsRequest
    PutManagedRuleSetVersionsResponse.add_member(:next_lock_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LockToken, location_name: 'NextLockToken', traits: {"smithy.api#documentation" => "<p>A token used for optimistic locking. WAF returns a token to your <code>get</code> and <code>list</code> requests, to mark the state of the entity at the time of the request. To make changes to the entity associated with the token, you provide the token to operations like <code>update</code> and <code>delete</code>. WAF uses the token to ensure that no changes have been made to the entity since you last retrieved it. If a change has been made, the update fails with a <code>WAFOptimisticLockException</code>. If this happens, perform another <code>get</code>, and use the new token returned by that operation. </p>"}))
