    PutPermissionPolicyRequest.add_member(:resource_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ResourceArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the <a>RuleGroup</a> to which you want to\n         attach the policy.</p>", "smithy.api#required" => {}}))
    PutPermissionPolicyRequest.add_member(:policy, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyString, location_name: 'Policy', traits: {"smithy.api#documentation" => "<p>The policy to attach to the specified rule group. </p>\n         <p>The policy specifications must conform to the following:</p>\n         <ul>\n            <li>\n               <p>The policy must be composed using IAM Policy version 2012-10-17.</p>\n            </li>\n            <li>\n               <p>The policy must include specifications for <code>Effect</code>, <code>Action</code>, and <code>Principal</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Effect</code> must specify <code>Allow</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Action</code> must specify <code>wafv2:CreateWebACL</code>, <code>wafv2:UpdateWebACL</code>, and \n             <code>wafv2:PutFirewallManagerRuleGroups</code> and may optionally specify <code>wafv2:GetRuleGroup</code>. \n                 WAF rejects any extra actions or wildcard actions in the policy.</p>\n            </li>\n            <li>\n               <p>The policy must not include a <code>Resource</code> parameter.</p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/IAM/latest/UserGuide/access_policies.html\">IAM Policies</a>.  </p>", "smithy.api#required" => {}}))
