    RateBasedStatementAggregateKeyType.add_member(:constant, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CONSTANT', traits: {"smithy.api#enumValue" => "CONSTANT"}))
    RateBasedStatementCustomKey.add_member(:header, Smithy::Schema::Shapes::ShapeRef.new(shape: RateLimitHeader, location_name: 'Header', traits: {"smithy.api#documentation" => "<p>Use the value of a header in the request as an aggregate key. Each distinct value in the header contributes to the aggregation instance. If you use a single \n      header as your custom key, then each value fully defines an aggregation instance. </p>"}))
    RateBasedStatementCustomKey.add_member(:cookie, Smithy::Schema::Shapes::ShapeRef.new(shape: RateLimitCookie, location_name: 'Cookie', traits: {"smithy.api#documentation" => "<p>Use the value of a cookie in the request as an aggregate key. Each distinct value in the cookie contributes to the aggregation instance. If you use a single\n    cookie as your custom key, then each value fully defines an aggregation instance. </p>"}))
    RateBasedStatementCustomKey.add_member(:query_argument, Smithy::Schema::Shapes::ShapeRef.new(shape: RateLimitQueryArgument, location_name: 'QueryArgument', traits: {"smithy.api#documentation" => "<p>Use the specified query argument as an aggregate key. Each distinct value for the named query argument contributes to the aggregation instance. If you \n      use a single query argument as your custom key, then each value fully defines an aggregation instance.  </p>"}))
