    RateBasedStatementCustomKey.add_member(:label_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: RateLimitLabelNamespace, location_name: 'LabelNamespace', traits: {"smithy.api#documentation" => "<p>Use the specified label namespace as an aggregate key. Each distinct fully qualified label name that has the specified label namespace contributes to the aggregation instance. If you use just one label namespace as your custom key, then each label name fully defines an aggregation instance.  </p>\n         <p>This uses only labels that have been added to the request by rules that are evaluated before this rate-based rule in the web ACL. </p>\n         <p>For information about label namespaces and names, see \n           <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-rule-label-requirements.html\">Label syntax and naming requirements</a> in the <i>WAF Developer Guide</i>.</p>"}))
