    ResponseInspectionBodyContains.add_member(:success_strings, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspectionBodyContainsSuccessStrings, location_name: 'SuccessStrings', traits: {"smithy.api#documentation" => "<p>Strings in the body of the response that indicate a successful login or account creation attempt. To be counted as a success, the string can be anywhere in the body and must be an exact match, including case. Each string must be unique among the success and failure strings. </p>\n         <p>JSON examples: <code>\"SuccessStrings\": [ \"Login successful\" ]</code> and <code>\"SuccessStrings\": [ \"Account creation successful\", \"Welcome to our site!\" ]</code>\n         </p>", "smithy.api#required" => {}}))
    ResponseInspectionBodyContains.add_member(:failure_strings, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspectionBodyContainsFailureStrings, location_name: 'FailureStrings', traits: {"smithy.api#documentation" => "<p>Strings in the body of the response that indicate a failed login or account creation attempt. To be counted as a failure, the string can be anywhere in the body and must be an exact match, including case. Each string must be unique among the success and failure strings. </p>\n         <p>JSON example: <code>\"FailureStrings\": [ \"Request failed\" ]</code>\n         </p>", "smithy.api#required" => {}}))
