    ResponseInspectionHeader.add_member(:success_values, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspectionHeaderSuccessValues, location_name: 'SuccessValues', traits: {"smithy.api#documentation" => "<p>Values in the response header with the specified name that indicate a successful login or account creation attempt. To be counted as a success, the value must be an exact match, including case. Each value must be unique among the success and failure values. </p>\n         <p>JSON examples: <code>\"SuccessValues\": [ \"LoginPassed\", \"Successful login\" ]</code> and <code>\"SuccessValues\": [ \"AccountCreated\", \"Successful account creation\" ]</code>\n         </p>", "smithy.api#required" => {}}))
    ResponseInspectionHeader.add_member(:failure_values, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspectionHeaderFailureValues, location_name: 'FailureValues', traits: {"smithy.api#documentation" => "<p>Values in the response header with the specified name that indicate a failed login or account creation attempt. To be counted as a failure, the value must be an exact match, including case. Each value must be unique among the success and failure values. </p>\n         <p>JSON examples: <code>\"FailureValues\": [ \"LoginFailed\", \"Failed login\" ]</code> and <code>\"FailureValues\": [ \"AccountCreationFailed\" ]</code>\n         </p>", "smithy.api#required" => {}}))
