    ResponseInspectionJson.add_member(:identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: FieldIdentifier, location_name: 'Identifier', traits: {"smithy.api#documentation" => "<p>The identifier for the value to match against in the JSON. The identifier must be an exact match, including case.</p>\n         <p>JSON examples: <code>\"Identifier\": [ \"/login/success\" ]</code> and <code>\"Identifier\": [ \"/sign-up/success\" ]</code>\n         </p>", "smithy.api#required" => {}}))
    ResponseInspectionJson.add_member(:success_values, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspectionJsonSuccessValues, location_name: 'SuccessValues', traits: {"smithy.api#documentation" => "<p>Values for the specified identifier in the response JSON that indicate a successful login or account creation attempt. To be counted as a success, the value must be an exact match, including case. Each value must be unique among the success and failure values. </p>\n         <p>JSON example: <code>\"SuccessValues\": [ \"True\", \"Succeeded\" ]</code>\n         </p>", "smithy.api#required" => {}}))
    ResponseInspectionJson.add_member(:failure_values, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspectionJsonFailureValues, location_name: 'FailureValues', traits: {"smithy.api#documentation" => "<p>Values for the specified identifier in the response JSON that indicate a failed login or account creation attempt. To be counted as a failure, the value must be an exact match, including case. Each value must be unique among the success and failure values. </p>\n         <p>JSON example: <code>\"FailureValues\": [ \"False\", \"Failed\" ]</code>\n         </p>", "smithy.api#required" => {}}))
