    ResponseInspectionStatusCode.add_member(:success_codes, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseInspectionStatusCodeSuccessCodes, location_name: 'SuccessCodes', traits: {"smithy.api#documentation" => "<p>Status codes in the response that indicate a successful login or account creation attempt. To be counted as a success, the response status code must match one of these. Each code must be unique among the success and failure status codes. </p>\n         <p>JSON example: <code>\"SuccessCodes\": [ 200, 201 ]</code>\n         </p>", "smithy.api#required" => {}}))
