    Rule.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the rule. </p>\n         <p>If you change the name of a <code>Rule</code> after you create\n           it and you want the rule's metric name to reflect the change, update the metric name in the rule's <code>VisibilityConfig</code> settings. WAF \n          doesn't automatically update the metric name when you update the rule name. </p>", "smithy.api#required" => {}}))
    Rule.add_member(:priority, Smithy::Schema::Shapes::ShapeRef.new(shape: RulePriority, location_name: 'Priority', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>If you define more than one <code>Rule</code> in a <code>WebACL</code>, WAF\n         evaluates each request against the <code>Rules</code> in order based on the value of\n            <code>Priority</code>. WAF processes rules with lower priority first. The priorities\n         don't need to be consecutive, but they must all be different.</p>", "smithy.api#required" => {}}))
    Rule.add_member(:statement, Smithy::Schema::Shapes::ShapeRef.new(shape: Statement, location_name: 'Statement', traits: {"smithy.api#documentation" => "<p>The WAF processing statement for the rule, for example <a>ByteMatchStatement</a> or <a>SizeConstraintStatement</a>. </p>", "smithy.api#required" => {}}))
    Rule.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleAction, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The action that WAF should take on a web request when it matches the rule statement. Settings at the web ACL level can override the rule action setting. </p>\n         <p>This is used only for rules whose statements do not reference a rule group. Rule statements that reference a rule group include <code>RuleGroupReferenceStatement</code> and <code>ManagedRuleGroupStatement</code>. </p>\n         <p>You must specify either this <code>Action</code> setting or the rule <code>OverrideAction</code> setting, but not both:</p>\n         <ul>\n            <li>\n               <p>If the rule statement does not reference a rule group, use this rule action setting and not the rule override action setting. </p>\n            </li>\n            <li>\n               <p>If the rule statement references a rule group, use the override action setting and not this action setting.  </p>\n            </li>\n         </ul>"}))
    Rule.add_member(:override_action, Smithy::Schema::Shapes::ShapeRef.new(shape: OverrideAction, location_name: 'OverrideAction', traits: {"smithy.api#documentation" => "<p>The action to use in the place of the action that results from the rule group evaluation. Set the override action to none to leave the result of the rule group alone. Set it to count to override the result to count only. </p>\n         <p>You can only use this for rule statements that reference a rule group, like <code>RuleGroupReferenceStatement</code> and <code>ManagedRuleGroupStatement</code>. </p>\n         <note>\n            <p>This option is usually set to none. It does not affect how the rules in the rule group are evaluated. If you want the rules in the rule group to only count  \n  matches, do not use this and instead use the rule action override option, with <code>Count</code> action, in your rule group reference statement settings. </p>\n         </note>"}))
    Rule.add_member(:rule_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: Labels, location_name: 'RuleLabels', traits: {"smithy.api#documentation" => "<p>Labels to apply to web requests that match the rule match statement. WAF applies\n         fully qualified labels to matching web requests. A fully qualified label is the\n         concatenation of a label namespace and a rule label. The rule's rule group or web ACL\n         defines the label namespace. </p>\n         <note>\n            <p>Any rule that isn't a rule group reference statement or managed rule group statement can add labels to matching web requests.</p>\n         </note>\n         <p>Rules that run after this rule in the web ACL can match against these labels using a\n            <code>LabelMatchStatement</code>.</p>\n         <p>For each label, provide a case-sensitive string containing optional namespaces and a\n         label name, according to the following guidelines:</p>\n         <ul>\n            <li>\n               <p>Separate each component of the label with a colon. </p>\n            </li>\n            <li>\n               <p>Each namespace or name can have up to 128 characters.</p>\n            </li>\n            <li>\n               <p>You can specify up to 5 namespaces in a label.</p>\n            </li>\n            <li>\n               <p>Don't use the following reserved words in your label specification:\n                  <code>aws</code>, <code>waf</code>, <code>managed</code>, <code>rulegroup</code>,\n                  <code>webacl</code>, <code>regexpatternset</code>, or <code>ipset</code>.</p>\n            </li>\n         </ul>\n         <p>For example, <code>myLabelName</code> or <code>nameSpace1:nameSpace2:myLabelName</code>.\n      </p>"}))
    Rule.add_member(:visibility_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VisibilityConfig, location_name: 'VisibilityConfig', traits: {"smithy.api#documentation" => "<p>Defines and enables Amazon CloudWatch metrics and web request sample collection.  </p>\n         <p>If you change the name of a <code>Rule</code> after you create\n          it and you want the rule's metric name to reflect the change, update the metric name as well. WAF \n          doesn't automatically update the metric name. </p>", "smithy.api#required" => {}}))
    Rule.add_member(:captcha_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptchaConfig, location_name: 'CaptchaConfig', traits: {"smithy.api#documentation" => "<p>Specifies how WAF should handle <code>CAPTCHA</code> evaluations. If you don't specify this, WAF uses the <code>CAPTCHA</code> configuration that's defined for the web ACL. </p>"}))
    Rule.add_member(:challenge_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeConfig, location_name: 'ChallengeConfig', traits: {"smithy.api#documentation" => "<p>Specifies how WAF should handle <code>Challenge</code> evaluations. If you don't specify this, WAF uses the challenge configuration that's defined for the web ACL. </p>"}))
