    RuleAction.add_member(:allow, Smithy::Schema::Shapes::ShapeRef.new(shape: AllowAction, location_name: 'Allow', traits: {"smithy.api#documentation" => "<p>Instructs WAF to allow the web request.</p>"}))
    RuleAction.add_member(:count, Smithy::Schema::Shapes::ShapeRef.new(shape: CountAction, location_name: 'Count', traits: {"smithy.api#documentation" => "<p>Instructs WAF to count the web request and then continue evaluating the request using the remaining rules in the web ACL.</p>"}))
