    RuleActionOverride.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the rule to override.</p>\n         <note>\n            <p>Take care to verify the rule names in your overrides. If you provide a rule name that doesn't match the name of any rule in the rule group, WAF doesn't return an error and doesn't apply the override setting.</p>\n         </note>", "smithy.api#required" => {}}))
    RuleActionOverride.add_member(:action_to_use, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleAction, location_name: 'ActionToUse', traits: {"smithy.api#documentation" => "<p>The override action to use, in place of the configured action of the rule in the rule group. </p>", "smithy.api#required" => {}}))
