    RuleGroup.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the rule group. You cannot change the name of a rule group after you create it.</p>", "smithy.api#required" => {}}))
    RuleGroup.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>A unique identifier for the rule group. This ID is returned in the responses to create and list commands. You provide it to operations like update and delete.</p>", "smithy.api#required" => {}}))
    RuleGroup.add_member(:capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityUnit, location_name: 'Capacity', traits: {"smithy.api#documentation" => "<p>The web ACL capacity units (WCUs) required for this rule group.</p>\n         <p>When you create your own rule group, you define this, and you cannot change it after creation. \n          When you add or modify the rules in a rule group, WAF enforces this limit. You can check the capacity \n          for a set of rules using <a>CheckCapacity</a>.</p>\n         <p>WAF uses WCUs to calculate and control the operating\n         resources that are used to run your rules, rule groups, and web ACLs. WAF\n         calculates capacity differently for each rule type, to reflect the relative cost of each rule. \n         Simple rules that cost little to run use fewer WCUs than more complex rules\n\t\t\t\tthat use more processing power. \n\t\t\t\tRule group capacity is fixed at creation, which helps users plan their  \n         web ACL WCU usage when they use a rule group. For more information, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/aws-waf-capacity-units.html\">WAF web ACL capacity units (WCU)</a> \n    in the <i>WAF Developer Guide</i>. </p>", "smithy.api#required" => {}}))
    RuleGroup.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the entity.</p>", "smithy.api#required" => {}}))
    RuleGroup.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the rule group that helps with identification. </p>"}))
    RuleGroup.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: Rules, location_name: 'Rules', traits: {"smithy.api#documentation" => "<p>The <a>Rule</a> statements used to identify the web requests that you \n         want to manage. Each rule includes one top-level statement that WAF uses to identify matching  \n         web requests, and parameters that govern how WAF handles them. \n      </p>"}))
    RuleGroup.add_member(:visibility_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VisibilityConfig, location_name: 'VisibilityConfig', traits: {"smithy.api#documentation" => "<p>Defines and enables Amazon CloudWatch metrics and web request sample collection.  </p>", "smithy.api#required" => {}}))
    RuleGroup.add_member(:label_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelName, location_name: 'LabelNamespace', traits: {"smithy.api#documentation" => "<p>The label namespace prefix for this rule group. All labels added by rules in this rule group have this prefix. </p>\n         <ul>\n            <li>\n               <p>The syntax for the label namespace prefix for your rule groups is the following: </p>\n               <p>\n                  <code>awswaf:<account ID>:rulegroup:<rule group name>:</code>\n               </p>\n            </li>\n            <li>\n               <p>When a rule with a label matches a web request, WAF adds the fully qualified label to the request. A fully qualified label is made up of the label namespace from the rule group or web ACL where the rule is defined and the label from the rule, separated by a colon: </p>\n               <p>\n                  <code><label namespace>:<label from rule></code>\n               </p>\n            </li>\n         </ul>"}))
    RuleGroup.add_member(:custom_response_bodies, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomResponseBodies, location_name: 'CustomResponseBodies', traits: {"smithy.api#documentation" => "<p>A map of custom response keys and content bodies. When you create a rule with a block action, you can send a custom response to the web request. You define these for the rule group, and then use them in the rules that you define in the rule group. </p>\n         <p>For information about customizing web requests and responses, \n           see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-custom-request-response.html\">Customizing web requests and responses in WAF</a> \n    in the <i>WAF Developer Guide</i>. </p>\n         <p>For information about the limits on count and size for custom request and response settings, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/limits.html\">WAF quotas</a> \n     in the <i>WAF Developer Guide</i>. </p>"}))
    RuleGroup.add_member(:available_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelSummaries, location_name: 'AvailableLabels', traits: {"smithy.api#documentation" => "<p>The labels that one or more rules in this rule group add to matching web requests. These labels are defined in the <code>RuleLabels</code> for a <a>Rule</a>.</p>"}))
    RuleGroup.add_member(:consumed_labels, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelSummaries, location_name: 'ConsumedLabels', traits: {"smithy.api#documentation" => "<p>The labels that one or more rules in this rule group match against in label match statements. These labels are defined in a <code>LabelMatchStatement</code> specification, in the <a>Statement</a> definition of a rule.  </p>"}))
    RuleGroup.type = Types::RuleGroup
    RuleGroupReferenceStatement.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the entity.</p>", "smithy.api#required" => {}}))
    RuleGroupReferenceStatement.add_member(:excluded_rules, Smithy::Schema::Shapes::ShapeRef.new(shape: ExcludedRules, location_name: 'ExcludedRules', traits: {"smithy.api#documentation" => "<p>Rules in the referenced rule group whose actions are set to <code>Count</code>. </p>\n         <note>\n            <p>Instead of this option, use <code>RuleActionOverrides</code>. It accepts any valid action setting, including <code>Count</code>.</p>\n         </note>"}))
    RuleGroupReferenceStatement.add_member(:rule_action_overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleActionOverrides, location_name: 'RuleActionOverrides', traits: {"smithy.api#documentation" => "<p>Action settings to use in the place of the rule actions that are configured inside the rule group. You specify one override for each rule whose action you want to change. </p>\n         <note>\n            <p>Verify the rule names in your overrides carefully. With managed rule groups, WAF silently ignores any override that uses an invalid rule name. With customer-owned rule groups, invalid rule names in your overrides will cause web ACL updates to fail. An invalid rule name is any name that doesn't exactly match the case-sensitive name of an existing rule in the rule group.</p>\n         </note>\n         <p>You can use overrides for testing, for example you can override all of rule actions to <code>Count</code> and then monitor the resulting count metrics to understand how the rule group would handle your web traffic. You can also permanently override some or all actions, to modify how the rule group manages your web traffic.</p>"}))
    RuleGroupReferenceStatement.type = Types::RuleGroupReferenceStatement
    RuleGroupSummaries.member = Smithy::Schema::Shapes::ShapeRef.new(shape: RuleGroupSummary)
    RuleGroupSummary.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the data type instance. You cannot change the name after you create the instance.</p>"}))
    RuleGroupSummary.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>A unique identifier for the rule group. This ID is returned in the responses to create and list commands. You provide it to operations like update and delete.</p>"}))
    RuleGroupSummary.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the rule group that helps with identification. </p>"}))
    RuleGroupSummary.add_member(:lock_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LockToken, location_name: 'LockToken', traits: {"smithy.api#documentation" => "<p>A token used for optimistic locking. WAF returns a token to your <code>get</code> and <code>list</code> requests, to mark the state of the entity at the time of the request. To make changes to the entity associated with the token, you provide the token to operations like <code>update</code> and <code>delete</code>. WAF uses the token to ensure that no changes have been made to the entity since you last retrieved it. If a change has been made, the update fails with a <code>WAFOptimisticLockException</code>. If this happens, perform another <code>get</code>, and use the new token returned by that operation. </p>"}))
    RuleGroupSummary.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the entity.</p>"}))
    RuleGroupSummary.type = Types::RuleGroupSummary
    RuleSummaries.member = Smithy::Schema::Shapes::ShapeRef.new(shape: RuleSummary)
    RuleSummary.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the rule. </p>"}))
    RuleSummary.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleAction, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The action that WAF should take on a web request when it matches a rule's\n         statement. Settings at the web ACL level can override the rule action setting. </p>"}))
    RuleSummary.type = Types::RuleSummary
    Rules.member = Smithy::Schema::Shapes::ShapeRef.new(shape: Rule)
    SampledHTTPRequest.add_member(:request, Smithy::Schema::Shapes::ShapeRef.new(shape: HTTPRequest, location_name: 'Request', traits: {"smithy.api#documentation" => "<p>A complex type that contains detailed information about the request.</p>", "smithy.api#required" => {}}))
    SampledHTTPRequest.add_member(:weight, Smithy::Schema::Shapes::ShapeRef.new(shape: SampleWeight, location_name: 'Weight', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>A value that indicates how one result in the response relates proportionally to other\n         results in the response. For example, a result that has a weight of <code>2</code>\n         represents roughly twice as many web requests as a result that has a weight of\n            <code>1</code>.</p>", "smithy.api#required" => {}}))
    SampledHTTPRequest.add_member(:timestamp, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'Timestamp', traits: {"smithy.api#documentation" => "<p>The time at which WAF received the request from your Amazon Web Services resource, in Unix time\n         format (in seconds).</p>"}))
    SampledHTTPRequest.add_member(:action, Smithy::Schema::Shapes::ShapeRef.new(shape: Action, location_name: 'Action', traits: {"smithy.api#documentation" => "<p>The action that WAF applied to the request.</p>"}))
    SampledHTTPRequest.add_member(:rule_name_within_rule_group, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'RuleNameWithinRuleGroup', traits: {"smithy.api#documentation" => "<p>The name of the <code>Rule</code> that the request matched. For managed rule groups, the\n         format for this name is <code><vendor name>#<managed rule group name>#<rule\n            name></code>. For your own rule groups, the format for this name is <code><rule\n            group name>#<rule name></code>. If the rule is not in a rule group, this field\n         is absent. </p>"}))
    SampledHTTPRequest.add_member(:request_headers_inserted, Smithy::Schema::Shapes::ShapeRef.new(shape: HTTPHeaders, location_name: 'RequestHeadersInserted', traits: {"smithy.api#documentation" => "<p>Custom request headers inserted by WAF into the request, according to the custom\n         request configuration for the matching rule action.</p>"}))
    SampledHTTPRequest.add_member(:response_code_sent, Smithy::Schema::Shapes::ShapeRef.new(shape: ResponseStatusCode, location_name: 'ResponseCodeSent', traits: {"smithy.api#documentation" => "<p>The response code that was sent for the request.</p>"}))
    SampledHTTPRequest.add_member(:labels, Smithy::Schema::Shapes::ShapeRef.new(shape: Labels, location_name: 'Labels', traits: {"smithy.api#documentation" => "<p>Labels applied to the web request by matching rules. WAF applies fully qualified\n         labels to matching web requests. A fully qualified label is the concatenation of a label\n         namespace and a rule label. The rule's rule group or web ACL defines the label namespace. </p>\n         <p>For example,\n            <code>awswaf:111122223333:myRuleGroup:testRules:testNS1:testNS2:labelNameA</code> or\n            <code>awswaf:managed:aws:managed-rule-set:header:encoding:utf8</code>. </p>"}))
    SampledHTTPRequest.add_member(:captcha_response, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptchaResponse, location_name: 'CaptchaResponse', traits: {"smithy.api#documentation" => "<p>The <code>CAPTCHA</code> response for the request.</p>"}))
    SampledHTTPRequest.add_member(:challenge_response, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeResponse, location_name: 'ChallengeResponse', traits: {"smithy.api#documentation" => "<p>The <code>Challenge</code> response for the request.</p>"}))
    SampledHTTPRequest.add_member(:overridden_action, Smithy::Schema::Shapes::ShapeRef.new(shape: Action, location_name: 'OverriddenAction', traits: {"smithy.api#documentation" => "<p>Used only for rule group rules that have a rule action override in place in the web ACL. This is the action that the rule group rule is configured for, and not the action that was applied to the request. The action that WAF applied is the <code>Action</code> value. </p>"}))
    SampledHTTPRequest.type = Types::SampledHTTPRequest
    SampledHTTPRequests.member = Smithy::Schema::Shapes::ShapeRef.new(shape: SampledHTTPRequest)
    Scope.add_member(:cloudfront, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CLOUDFRONT', traits: {"smithy.api#enumValue" => "CLOUDFRONT"}))
    Scope.add_member(:regional, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'REGIONAL', traits: {"smithy.api#enumValue" => "REGIONAL"}))
    SensitivityLevel.add_member(:low, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LOW', traits: {"smithy.api#enumValue" => "LOW"}))
    SensitivityLevel.add_member(:high, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HIGH', traits: {"smithy.api#enumValue" => "HIGH"}))
    SensitivityToAct.add_member(:low, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LOW', traits: {"smithy.api#enumValue" => "LOW"}))
    SensitivityToAct.add_member(:medium, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MEDIUM', traits: {"smithy.api#enumValue" => "MEDIUM"}))
    SensitivityToAct.add_member(:high, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HIGH', traits: {"smithy.api#enumValue" => "HIGH"}))
    SingleHeader.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: FieldToMatchData, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the query header to inspect.</p>", "smithy.api#required" => {}}))
    SingleHeader.type = Types::SingleHeader
    SingleQueryArgument.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: FieldToMatchData, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the query argument to inspect.</p>", "smithy.api#required" => {}}))
    SingleQueryArgument.type = Types::SingleQueryArgument
    SizeConstraintStatement.add_member(:field_to_match, Smithy::Schema::Shapes::ShapeRef.new(shape: FieldToMatch, location_name: 'FieldToMatch', traits: {"smithy.api#documentation" => "<p>The part of the web request that you want WAF to inspect. </p>", "smithy.api#required" => {}}))
    SizeConstraintStatement.add_member(:comparison_operator, Smithy::Schema::Shapes::ShapeRef.new(shape: ComparisonOperator, location_name: 'ComparisonOperator', traits: {"smithy.api#documentation" => "<p>The operator to use to compare the request part to the size setting. </p>", "smithy.api#required" => {}}))
    SizeConstraintStatement.add_member(:size, Smithy::Schema::Shapes::ShapeRef.new(shape: Size, location_name: 'Size', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The size, in byte, to compare to the request part, after any transformations.</p>", "smithy.api#required" => {}}))
    SizeConstraintStatement.add_member(:text_transformations, Smithy::Schema::Shapes::ShapeRef.new(shape: TextTransformations, location_name: 'TextTransformations', traits: {"smithy.api#documentation" => "<p>Text transformations eliminate some of the unusual formatting that attackers use in web requests in an effort to bypass detection. Text transformations are used in rule match statements, to transform the <code>FieldToMatch</code> request component before inspecting it, and they're used in rate-based rule statements, to transform request components before using them as custom aggregation keys. If you specify one or more transformations to apply, WAF performs all transformations on the specified content, starting from the lowest priority setting, and then uses the transformed component contents. </p>", "smithy.api#required" => {}}))
    SizeConstraintStatement.type = Types::SizeConstraintStatement
    SizeInspectionLimit.add_member(:kb_16, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'KB_16', traits: {"smithy.api#enumValue" => "KB_16"}))
    SizeInspectionLimit.add_member(:kb_32, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'KB_32', traits: {"smithy.api#enumValue" => "KB_32"}))
    SizeInspectionLimit.add_member(:kb_48, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'KB_48', traits: {"smithy.api#enumValue" => "KB_48"}))
    SizeInspectionLimit.add_member(:kb_64, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'KB_64', traits: {"smithy.api#enumValue" => "KB_64"}))
    SqliMatchStatement.add_member(:field_to_match, Smithy::Schema::Shapes::ShapeRef.new(shape: FieldToMatch, location_name: 'FieldToMatch', traits: {"smithy.api#documentation" => "<p>The part of the web request that you want WAF to inspect. </p>", "smithy.api#required" => {}}))
    SqliMatchStatement.add_member(:text_transformations, Smithy::Schema::Shapes::ShapeRef.new(shape: TextTransformations, location_name: 'TextTransformations', traits: {"smithy.api#documentation" => "<p>Text transformations eliminate some of the unusual formatting that attackers use in web requests in an effort to bypass detection. Text transformations are used in rule match statements, to transform the <code>FieldToMatch</code> request component before inspecting it, and they're used in rate-based rule statements, to transform request components before using them as custom aggregation keys. If you specify one or more transformations to apply, WAF performs all transformations on the specified content, starting from the lowest priority setting, and then uses the transformed component contents. </p>", "smithy.api#required" => {}}))
    SqliMatchStatement.add_member(:sensitivity_level, Smithy::Schema::Shapes::ShapeRef.new(shape: SensitivityLevel, location_name: 'SensitivityLevel', traits: {"smithy.api#documentation" => "<p>The sensitivity that you want WAF to use to inspect for SQL injection attacks. </p>\n         <p>\n            <code>HIGH</code> detects more attacks, but might generate more false positives, \n       especially if your web requests frequently contain unusual strings. \n       For information about identifying and mitigating false positives, see \n           <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/web-acl-testing.html\">Testing and tuning</a> in the                                                                             \n           <i>WAF Developer Guide</i>.</p>\n         <p>\n            <code>LOW</code> is generally a better choice for resources that already have other \n           protections against SQL injection attacks or that have a low tolerance for false positives. </p>\n         <p>Default: <code>LOW</code>\n         </p>"}))
    SqliMatchStatement.type = Types::SqliMatchStatement
    Statement.add_member(:byte_match_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: ByteMatchStatement, location_name: 'ByteMatchStatement', traits: {"smithy.api#documentation" => "<p>A rule statement that defines a string match search for WAF to apply to web requests. The byte match statement provides the bytes to search for, the location in requests that you want WAF to search, and other settings. The bytes to search for are typically a string that corresponds with ASCII characters. In the WAF console and the developer guide, this is called a string match statement.</p>"}))
    Statement.add_member(:sqli_match_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: SqliMatchStatement, location_name: 'SqliMatchStatement', traits: {"smithy.api#documentation" => "<p>A rule statement that inspects for malicious SQL code. Attackers insert malicious SQL code into web requests to do things like modify your database or extract data from it. </p>"}))
    Statement.add_member(:xss_match_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: XssMatchStatement, location_name: 'XssMatchStatement', traits: {"smithy.api#documentation" => "<p>A rule statement that inspects for cross-site scripting (XSS) attacks. In XSS attacks, the attacker \nuses vulnerabilities in a benign website as a vehicle to inject malicious client-site scripts into other legitimate web browsers. </p>"}))
    Statement.add_member(:size_constraint_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: SizeConstraintStatement, location_name: 'SizeConstraintStatement', traits: {"smithy.api#documentation" => "<p>A rule statement that compares a number of bytes against the size of a request component, using a comparison operator, such as greater than (>) or less than (<). For example, you can use a size constraint statement to look for query strings that are longer than 100 bytes. </p>\n         <p>If you configure WAF to inspect the request body, WAF inspects only the number of bytes in the body up to the limit for the web ACL and protected resource type. If you know that the request body for your web requests should never exceed the inspection limit, you can use a size constraint statement to block requests that have a larger request body size. For more information about the inspection limits, see <code>Body</code> and <code>JsonBody</code> settings for the <code>FieldToMatch</code> data type. </p>\n         <p>If you choose URI for the value of Part of the request to filter on, the slash (/) in the URI counts as one character. For example, the URI <code>/logo.jpg</code> is nine characters long.</p>"}))
    Statement.add_member(:geo_match_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: GeoMatchStatement, location_name: 'GeoMatchStatement', traits: {"smithy.api#documentation" => "<p>A rule statement that labels web requests by country and region and that matches against web requests based on country code. A geo match rule labels every request that it inspects regardless of whether it finds a match.</p>\n         <ul>\n            <li>\n               <p>To manage requests only by country, you can use this statement by itself and specify the countries that you want to match against in the <code>CountryCodes</code> array. </p>\n            </li>\n            <li>\n               <p>Otherwise, configure your geo match rule with Count action so that it only labels requests. Then, add one or more label match rules to run after the geo match rule and configure them to match against the geographic labels and handle the requests as needed. </p>\n            </li>\n         </ul>\n         <p>WAF labels requests using the alpha-2 country and region codes from the International Organization for Standardization (ISO) 3166 standard. WAF determines the codes using either the IP address in the web request origin or, if you specify it, the address in the geo match <code>ForwardedIPConfig</code>. </p>\n         <p>If you use the web request origin, the label formats are <code>awswaf:clientip:geo:region:<ISO country code>-<ISO region code></code> and <code>awswaf:clientip:geo:country:<ISO country code></code>.</p>\n         <p>If you use a forwarded IP address, the label formats are <code>awswaf:forwardedip:geo:region:<ISO country code>-<ISO region code></code> and <code>awswaf:forwardedip:geo:country:<ISO country code></code>.</p>\n         <p>For additional details, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-rule-statement-type-geo-match.html\">Geographic match rule statement</a> in the <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-chapter.html\">WAF Developer Guide</a>. </p>"}))
    Statement.add_member(:rule_group_reference_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: RuleGroupReferenceStatement, location_name: 'RuleGroupReferenceStatement', traits: {"smithy.api#documentation" => "<p>A rule statement used to run the rules that are defined in a <a>RuleGroup</a>. To use this, create a rule group with your rules, then provide the ARN of the rule group in this statement.</p>\n         <p>You cannot nest a <code>RuleGroupReferenceStatement</code>, for example for use inside a <code>NotStatement</code> or <code>OrStatement</code>. You cannot use a rule group\n      reference statement inside another rule group. You can only reference a rule group as a top-level statement within a rule that you define in a web ACL.</p>"}))
    Statement.add_member(:ip_set_reference_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: IPSetReferenceStatement, location_name: 'IPSetReferenceStatement', traits: {"smithy.api#documentation" => "<p>A rule statement used to detect web requests coming from particular IP addresses or address ranges. To use this, create an <a>IPSet</a> that specifies the addresses you want to detect, then use the ARN of that set in this statement. To create an IP set, see <a>CreateIPSet</a>.</p>\n         <p>Each IP set rule statement references an IP set. You create and maintain the set independent of your rules. This allows you to use the single set in multiple rules. When you update the referenced set, WAF automatically updates all rules that reference it.</p>"}))
    Statement.add_member(:regex_pattern_set_reference_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: RegexPatternSetReferenceStatement, location_name: 'RegexPatternSetReferenceStatement', traits: {"smithy.api#documentation" => "<p>A rule statement used to search web request components for matches with regular expressions. To use this, create a <a>RegexPatternSet</a> that specifies the expressions that you want to detect, then use the ARN of that set in this statement. A web request matches the pattern set rule statement if the request component matches any of the patterns in the set. To create a regex pattern set, see <a>CreateRegexPatternSet</a>.</p>\n         <p>Each regex pattern set rule statement references a regex pattern set. You create and maintain the set independent of your rules. This allows you to use the single set in multiple rules. When you update the referenced set, WAF automatically updates all rules that reference it.</p>"}))
    Statement.add_member(:rate_based_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: RateBasedStatement, location_name: 'RateBasedStatement', traits: {"smithy.api#documentation" => "<p>A rate-based rule counts incoming requests and rate limits requests when they are coming at too fast a rate. The rule categorizes requests according to your aggregation criteria, collects them into aggregation instances, and counts and rate limits the requests for each instance. </p>\n         <note>\n            <p>If you change any of these settings in a rule that's currently in use, the change resets the rule's rate limiting counts. This can pause the rule's rate limiting activities for up to a minute. </p>\n         </note>\n         <p>You can specify individual aggregation keys, like IP address or HTTP method. You can also specify aggregation key combinations, like IP address and HTTP method, or HTTP method, query argument, and cookie. </p>\n         <p>Each unique set of values for the aggregation keys that you specify is a separate aggregation instance, with the value from each key contributing to the aggregation instance definition. </p>\n         <p>For example, assume the rule evaluates web requests with the following IP address and HTTP method values: </p>\n         <ul>\n            <li>\n               <p>IP address 10.1.1.1, HTTP method POST</p>\n            </li>\n            <li>\n               <p>IP address 10.1.1.1, HTTP method GET</p>\n            </li>\n            <li>\n               <p>IP address 127.0.0.0, HTTP method POST</p>\n            </li>\n            <li>\n               <p>IP address 10.1.1.1, HTTP method GET</p>\n            </li>\n         </ul>\n         <p>The rule would create different aggregation instances according to your aggregation criteria, for example: </p>\n         <ul>\n            <li>\n               <p>If the aggregation criteria is just the IP address, then each individual address is an aggregation instance, and WAF counts requests separately for each. The aggregation instances and request counts for our example would be the following: </p>\n               <ul>\n                  <li>\n                     <p>IP address 10.1.1.1: count 3</p>\n                  </li>\n                  <li>\n                     <p>IP address 127.0.0.0: count 1</p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>If the aggregation criteria is HTTP method, then each individual HTTP method is an aggregation instance. The aggregation instances and request counts for our example would be the following: </p>\n               <ul>\n                  <li>\n                     <p>HTTP method POST: count 2</p>\n                  </li>\n                  <li>\n                     <p>HTTP method GET: count 2</p>\n                  </li>\n               </ul>\n            </li>\n            <li>\n               <p>If the aggregation criteria is IP address and HTTP method, then each IP address and each HTTP method would contribute to the combined aggregation instance. The aggregation instances and request counts for our example would be the following: </p>\n               <ul>\n                  <li>\n                     <p>IP address 10.1.1.1, HTTP method POST: count 1</p>\n                  </li>\n                  <li>\n                     <p>IP address 10.1.1.1, HTTP method GET: count 2</p>\n                  </li>\n                  <li>\n                     <p>IP address 127.0.0.0, HTTP method POST: count 1</p>\n                  </li>\n               </ul>\n            </li>\n         </ul>\n         <p>For any n-tuple of aggregation keys, each unique combination of values for the keys defines a separate aggregation instance, which WAF counts and rate-limits individually. </p>\n         <p>You can optionally nest another statement inside the rate-based statement, to narrow the scope of the rule so that it only counts and rate limits requests that match the nested statement. You can use this nested scope-down statement in conjunction with your aggregation key specifications or you can just count and rate limit all requests that match the scope-down statement, without additional aggregation. When you choose to just manage all requests that match a scope-down statement, the aggregation instance is singular for the rule. </p>\n         <p>You cannot nest a <code>RateBasedStatement</code> inside another statement, for example inside a <code>NotStatement</code> or <code>OrStatement</code>. You can define a <code>RateBasedStatement</code> inside a web ACL and inside a rule group. </p>\n         <p>For additional information about the options, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-rate-based-rules.html\">Rate limiting web requests using rate-based rules</a> \n    in the <i>WAF Developer Guide</i>. </p>\n         <p>If you only aggregate on the individual IP address or forwarded IP address, you can retrieve the list of IP addresses that WAF \n          is currently rate limiting for a rule through the API call <code>GetRateBasedStatementManagedKeys</code>. This option is not available\n      for other aggregation configurations.</p>\n         <p>WAF tracks and manages web requests separately for each instance of a rate-based rule that you use. For example, if you provide the same rate-based rule settings in two web ACLs, each of the two rule statements represents a separate instance of the rate-based rule and gets its own tracking and management by WAF. If you define a rate-based rule inside a rule group, and then use that rule group in multiple places, each use creates a separate instance of the rate-based rule that gets its own tracking and management by WAF. </p>"}))
    Statement.add_member(:and_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: AndStatement, location_name: 'AndStatement', traits: {"smithy.api#documentation" => "<p>A logical rule statement used to combine other rule statements with AND logic. You provide more than one <a>Statement</a> within the <code>AndStatement</code>. </p>"}))
    Statement.add_member(:or_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: OrStatement, location_name: 'OrStatement', traits: {"smithy.api#documentation" => "<p>A logical rule statement used to combine other rule statements with OR logic. You provide more than one <a>Statement</a> within the <code>OrStatement</code>. </p>"}))
    Statement.add_member(:not_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: NotStatement, location_name: 'NotStatement', traits: {"smithy.api#documentation" => "<p>A logical rule statement used to negate the results of another rule statement. You provide one <a>Statement</a> within the <code>NotStatement</code>.</p>"}))
    Statement.add_member(:managed_rule_group_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: ManagedRuleGroupStatement, location_name: 'ManagedRuleGroupStatement', traits: {"smithy.api#documentation" => "<p>A rule statement used to run the rules that are defined in a managed rule group. To use this, provide the vendor name and the name of the rule group in this statement. You can retrieve the required names by calling <a>ListAvailableManagedRuleGroups</a>.</p>\n         <p>You cannot nest a <code>ManagedRuleGroupStatement</code>, for example for use inside a <code>NotStatement</code> or <code>OrStatement</code>. You cannot use a managed rule group \n      inside another rule group. You can only reference a managed rule group as a top-level statement within a rule that you define in a web ACL.</p>\n         <note>\n            <p>You are charged additional fees when you use the WAF Bot Control managed rule group <code>AWSManagedRulesBotControlRuleSet</code>, the WAF Fraud Control account takeover prevention (ATP) managed rule group <code>AWSManagedRulesATPRuleSet</code>, or the WAF Fraud Control account creation fraud prevention (ACFP) managed rule group <code>AWSManagedRulesACFPRuleSet</code>. For more information, see <a href=\"http://aws.amazon.com/waf/pricing/\">WAF Pricing</a>.</p>\n         </note>"}))
    Statement.add_member(:label_match_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelMatchStatement, location_name: 'LabelMatchStatement', traits: {"smithy.api#documentation" => "<p>A rule statement to match against labels that have been added to the web request by rules that have already run in the web ACL. </p>\n         <p>The label match statement provides the label or namespace string to search for. The label string can represent a part or all of the fully qualified label name that had been added to the web request. Fully qualified labels have a prefix, optional namespaces, and label name. The prefix identifies the rule group or web ACL context of the rule that added the label.  If you do not provide the fully qualified name in your label match string, WAF performs the search for labels that were added in the same context as the label match statement. </p>"}))
    Statement.add_member(:regex_match_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: RegexMatchStatement, location_name: 'RegexMatchStatement', traits: {"smithy.api#documentation" => "<p>A rule statement used to search web request components for a match against a single regular expression. </p>"}))
    Statement.add_member(:asn_match_statement, Smithy::Schema::Shapes::ShapeRef.new(shape: AsnMatchStatement, location_name: 'AsnMatchStatement', traits: {"smithy.api#documentation" => "<p>A rule statement that inspects web traffic based on the Autonomous System Number (ASN) associated with the request's IP address.</p>\n         <p>For additional details, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-rule-statement-type-asn-match.html\">ASN match rule statement</a> in the <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-chapter.html\">WAF Developer Guide</a>. </p>"}))
