    TimeWindow.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestamp, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The beginning of the time range from which you want <code>GetSampledRequests</code> to\n         return a sample of the requests that your Amazon Web Services resource received. You must specify the\n         times in Coordinated Universal Time (UTC) format. UTC format includes the special\n         designator, <code>Z</code>. For example, <code>\"2016-09-27T14:50Z\"</code>. You can specify\n         any time range in the previous three hours.</p>", "smithy.api#required" => {}}))
