    UpdateIPSetRequest.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the IP set. You cannot change the name of an <code>IPSet</code> after you create it.</p>", "smithy.api#required" => {}}))
    UpdateIPSetRequest.add_member(:scope, Smithy::Schema::Shapes::ShapeRef.new(shape: Scope, location_name: 'Scope', traits: {"smithy.api#documentation" => "<p>Specifies whether this is for a global resource type, such as a Amazon CloudFront distribution. For an Amplify application, use <code>CLOUDFRONT</code>.</p>\n         <p>To work with CloudFront, you must also specify the Region US East (N. Virginia) as follows: </p>\n         <ul>\n            <li>\n               <p>CLI - Specify the Region when you use the CloudFront scope: <code>--scope=CLOUDFRONT --region=us-east-1</code>. </p>\n            </li>\n            <li>\n               <p>API and SDKs - For all calls, use the Region endpoint us-east-1. </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    UpdateIPSetRequest.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>A unique identifier for the set. This ID is returned in the responses to create and list commands. You provide it to operations like update and delete.</p>", "smithy.api#required" => {}}))
    UpdateIPSetRequest.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the IP set that helps with identification. </p>"}))
    UpdateIPSetRequest.add_member(:addresses, Smithy::Schema::Shapes::ShapeRef.new(shape: IPAddresses, location_name: 'Addresses', traits: {"smithy.api#documentation" => "<p>Contains an array of strings that specifies zero or more IP addresses or blocks of IP addresses that you want WAF to inspect for in incoming requests. All addresses must be specified using Classless Inter-Domain Routing (CIDR) notation. WAF supports all IPv4 and IPv6 CIDR ranges except for <code>/0</code>. </p>\n         <p>Example address strings: </p>\n         <ul>\n            <li>\n               <p>For requests that originated from the IP address 192.0.2.44, specify <code>192.0.2.44/32</code>.</p>\n            </li>\n            <li>\n               <p>For requests that originated from IP addresses from 192.0.2.0 to 192.0.2.255, specify \n               <code>192.0.2.0/24</code>.</p>\n            </li>\n            <li>\n               <p>For requests that originated from the IP address 1111:0000:0000:0000:0000:0000:0000:0111, specify <code>1111:0000:0000:0000:0000:0000:0000:0111/128</code>.</p>\n            </li>\n            <li>\n               <p>For requests that originated from IP addresses 1111:0000:0000:0000:0000:0000:0000:0000 to 1111:0000:0000:0000:ffff:ffff:ffff:ffff, specify <code>1111:0000:0000:0000:0000:0000:0000:0000/64</code>.</p>\n            </li>\n         </ul>\n         <p>For more information about CIDR notation, see the Wikipedia entry <a href=\"https://en.wikipedia.org/wiki/Classless_Inter-Domain_Routing\">Classless Inter-Domain Routing</a>.</p>\n         <p>Example JSON <code>Addresses</code> specifications: </p>\n         <ul>\n            <li>\n               <p>Empty array: <code>\"Addresses\": []</code>\n               </p>\n            </li>\n            <li>\n               <p>Array with one address: <code>\"Addresses\": [\"192.0.2.44/32\"]</code>\n               </p>\n            </li>\n            <li>\n               <p>Array with three addresses: <code>\"Addresses\": [\"192.0.2.44/32\", \"192.0.2.0/24\", \"192.0.0.0/16\"]</code>\n               </p>\n            </li>\n            <li>\n               <p>INVALID specification: <code>\"Addresses\": [\"\"]</code> INVALID </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    UpdateIPSetRequest.add_member(:lock_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LockToken, location_name: 'LockToken', traits: {"smithy.api#documentation" => "<p>A token used for optimistic locking. WAF returns a token to your <code>get</code> and <code>list</code> requests, to mark the state of the entity at the time of the request. To make changes to the entity associated with the token, you provide the token to operations like <code>update</code> and <code>delete</code>. WAF uses the token to ensure that no changes have been made to the entity since you last retrieved it. If a change has been made, the update fails with a <code>WAFOptimisticLockException</code>. If this happens, perform another <code>get</code>, and use the new token returned by that operation. </p>", "smithy.api#required" => {}}))
    UpdateIPSetRequest.type = Types::UpdateIPSetRequest
    UpdateIPSetResponse.add_member(:next_lock_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LockToken, location_name: 'NextLockToken', traits: {"smithy.api#documentation" => "<p>A token used for optimistic locking. WAF returns this token to your <code>update</code> requests. You use <code>NextLockToken</code> in the same manner as you use <code>LockToken</code>. </p>"}))
