    UpdateWebACLRequest.add_member(:data_protection_config, Smithy::Schema::Shapes::ShapeRef.new(shape: DataProtectionConfig, location_name: 'DataProtectionConfig', traits: {"smithy.api#documentation" => "<p>Specifies data protection to apply to the web request data for the web ACL. This is a web ACL level data protection option. </p>\n         <p>The data protection that you configure for the web ACL alters the data that's available for any other data collection activity, \n  including your WAF logging destinations, web ACL request sampling, and Amazon Security Lake data collection and management. Your other option for data protection is in the logging configuration, which only affects logging. </p>"}))
    UpdateWebACLRequest.add_member(:lock_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LockToken, location_name: 'LockToken', traits: {"smithy.api#documentation" => "<p>A token used for optimistic locking. WAF returns a token to your <code>get</code> and <code>list</code> requests, to mark the state of the entity at the time of the request. To make changes to the entity associated with the token, you provide the token to operations like <code>update</code> and <code>delete</code>. WAF uses the token to ensure that no changes have been made to the entity since you last retrieved it. If a change has been made, the update fails with a <code>WAFOptimisticLockException</code>. If this happens, perform another <code>get</code>, and use the new token returned by that operation. </p>", "smithy.api#required" => {}}))
    UpdateWebACLRequest.add_member(:custom_response_bodies, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomResponseBodies, location_name: 'CustomResponseBodies', traits: {"smithy.api#documentation" => "<p>A map of custom response keys and content bodies. When you create a rule with a block action, you can send a custom response to the web request. You define these for the web ACL, and then use them in the rules and default actions that you define in the web ACL. </p>\n         <p>For information about customizing web requests and responses, \n           see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-custom-request-response.html\">Customizing web requests and responses in WAF</a> \n    in the <i>WAF Developer Guide</i>. </p>\n         <p>For information about the limits on count and size for custom request and response settings, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/limits.html\">WAF quotas</a> \n     in the <i>WAF Developer Guide</i>. </p>"}))
    UpdateWebACLRequest.add_member(:captcha_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptchaConfig, location_name: 'CaptchaConfig', traits: {"smithy.api#documentation" => "<p>Specifies how WAF should handle <code>CAPTCHA</code> evaluations for rules that don't have their own <code>CaptchaConfig</code> settings. If you don't specify this, WAF uses its default settings for <code>CaptchaConfig</code>. </p>"}))
    UpdateWebACLRequest.add_member(:challenge_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeConfig, location_name: 'ChallengeConfig', traits: {"smithy.api#documentation" => "<p>Specifies how WAF should handle challenge evaluations for rules that don't have \ntheir own <code>ChallengeConfig</code> settings. If you don't specify this, WAF uses its default settings for <code>ChallengeConfig</code>. </p>"}))
    UpdateWebACLRequest.add_member(:token_domains, Smithy::Schema::Shapes::ShapeRef.new(shape: TokenDomains, location_name: 'TokenDomains', traits: {"smithy.api#documentation" => "<p>Specifies the domains that WAF should accept in a web request token. This enables the use of tokens across multiple protected websites. When WAF provides a token, it uses the domain of the Amazon Web Services resource that the web ACL is protecting. If you don't specify a list of token domains, WAF accepts tokens only for the domain of the protected resource. With a token domain list, WAF accepts the resource's host domain plus all domains in the token domain list, including their prefixed subdomains.</p>\n         <p>Example JSON: <code>\"TokenDomains\": { \"mywebsite.com\", \"myotherwebsite.com\" }</code>\n         </p>\n         <p>Public suffixes aren't allowed. For example, you can't use <code>gov.au</code> or <code>co.uk</code> as token domains.</p>"}))
    UpdateWebACLRequest.add_member(:association_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AssociationConfig, location_name: 'AssociationConfig', traits: {"smithy.api#documentation" => "<p>Specifies custom configurations for the associations between the web ACL and protected resources.  </p>\n         <p>Use this to customize the maximum size of the request body that your protected resources forward to WAF for inspection. You can \n    customize this setting for CloudFront, API Gateway, Amazon Cognito, App Runner, or Verified Access resources. The default setting is 16 KB (16,384 bytes). </p>\n         <note>\n            <p>You are charged additional fees when your protected resources forward body sizes that are larger than the default. For more information, see <a href=\"http://aws.amazon.com/waf/pricing/\">WAF Pricing</a>.</p>\n         </note>\n         <p>For Application Load Balancer and AppSync, the limit is fixed at 8 KB (8,192 bytes).</p>"}))
    UpdateWebACLRequest.add_member(:on_source_d_do_s_protection_config, Smithy::Schema::Shapes::ShapeRef.new(shape: OnSourceDDoSProtectionConfig, location_name: 'OnSourceDDoSProtectionConfig', traits: {"smithy.api#documentation" => "<p>Specifies the type of DDoS protection to apply to web request data for a web ACL. For most scenarios, it is recommended to use the default protection level, <code>ACTIVE_UNDER_DDOS</code>. \n   If a web ACL is associated with multiple Application Load Balancers, the changes you make to DDoS protection in that web ACL will apply to all associated Application Load Balancers.</p>"}))
