    WebACL.add_member(:id, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityId, location_name: 'Id', traits: {"smithy.api#documentation" => "<p>A unique identifier for the <code>WebACL</code>. This ID is returned in the responses to\n         create and list commands. You use this ID to do things like get, update, and delete a\n            <code>WebACL</code>.</p>", "smithy.api#required" => {}}))
    WebACL.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceArn, location_name: 'ARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the web ACL that you want to associate with the\n         resource.</p>", "smithy.api#required" => {}}))
    WebACL.add_member(:default_action, Smithy::Schema::Shapes::ShapeRef.new(shape: DefaultAction, location_name: 'DefaultAction', traits: {"smithy.api#documentation" => "<p>The action to perform if none of the <code>Rules</code> contained in the <code>WebACL</code> match. </p>", "smithy.api#required" => {}}))
    WebACL.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: EntityDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>A description of the web ACL that helps with identification. </p>"}))
    WebACL.add_member(:rules, Smithy::Schema::Shapes::ShapeRef.new(shape: Rules, location_name: 'Rules', traits: {"smithy.api#documentation" => "<p>The <a>Rule</a> statements used to identify the web requests that you \n         want to manage. Each rule includes one top-level statement that WAF uses to identify matching  \n         web requests, and parameters that govern how WAF handles them. \n      </p>"}))
    WebACL.add_member(:visibility_config, Smithy::Schema::Shapes::ShapeRef.new(shape: VisibilityConfig, location_name: 'VisibilityConfig', traits: {"smithy.api#documentation" => "<p>Defines and enables Amazon CloudWatch metrics and web request sample collection.  </p>", "smithy.api#required" => {}}))
    WebACL.add_member(:data_protection_config, Smithy::Schema::Shapes::ShapeRef.new(shape: DataProtectionConfig, location_name: 'DataProtectionConfig', traits: {"smithy.api#documentation" => "<p>Specifies data protection to apply to the web request data for the web ACL. This is a web ACL level data protection option. </p>\n         <p>The data protection that you configure for the web ACL alters the data that's available for any other data collection activity, \n  including your WAF logging destinations, web ACL request sampling, and Amazon Security Lake data collection and management. Your other option for data protection is in the logging configuration, which only affects logging. </p>"}))
    WebACL.add_member(:capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: ConsumedCapacity, location_name: 'Capacity', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The web ACL capacity units (WCUs) currently being used by this web ACL. </p>\n         <p>WAF uses WCUs to calculate and control the operating\n         resources that are used to run your rules, rule groups, and web ACLs. WAF\n         calculates capacity differently for each rule type, to reflect the relative cost of each rule. \n         Simple rules that cost little to run use fewer WCUs than more complex rules\n\t\t\t\tthat use more processing power. \n\t\t\t\tRule group capacity is fixed at creation, which helps users plan their  \n         web ACL WCU usage when they use a rule group. For more information, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/aws-waf-capacity-units.html\">WAF web ACL capacity units (WCU)</a> \n    in the <i>WAF Developer Guide</i>. </p>"}))
    WebACL.add_member(:pre_process_firewall_manager_rule_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: FirewallManagerRuleGroups, location_name: 'PreProcessFirewallManagerRuleGroups', traits: {"smithy.api#documentation" => "<p>The first set of rules for WAF to process in the web ACL. This is defined in an\n         Firewall Manager WAF policy and contains only rule group references. You can't alter these. Any\n         rules and rule groups that you define for the web ACL are prioritized after these. </p>\n         <p>In the Firewall Manager WAF policy, the Firewall Manager administrator can define a set of rule groups to run\n         first in the web ACL and a set of rule groups to run last. Within each set, the\n         administrator prioritizes the rule groups, to determine their relative processing\n         order.</p>"}))
    WebACL.add_member(:post_process_firewall_manager_rule_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: FirewallManagerRuleGroups, location_name: 'PostProcessFirewallManagerRuleGroups', traits: {"smithy.api#documentation" => "<p>The last set of rules for WAF to process in the web ACL. This is defined in an\n         Firewall Manager WAF policy and contains only rule group references. You can't alter these. Any\n         rules and rule groups that you define for the web ACL are prioritized before these. </p>\n         <p>In the Firewall Manager WAF policy, the Firewall Manager administrator can define a set of rule groups to run\n         first in the web ACL and a set of rule groups to run last. Within each set, the\n         administrator prioritizes the rule groups, to determine their relative processing\n         order.</p>"}))
    WebACL.add_member(:managed_by_firewall_manager, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ManagedByFirewallManager', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether this web ACL was created by Firewall Manager and is being managed by Firewall Manager. If true, then only Firewall Manager can\n          delete the web ACL or any Firewall Manager rule groups in the web ACL. \n           See also the properties <code>RetrofittedByFirewallManager</code>, <code>PreProcessFirewallManagerRuleGroups</code>, and <code>PostProcessFirewallManagerRuleGroups</code>. </p>"}))
    WebACL.add_member(:label_namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: LabelName, location_name: 'LabelNamespace', traits: {"smithy.api#documentation" => "<p>The label namespace prefix for this web ACL. All labels added by rules in this web ACL have this prefix. </p>\n         <ul>\n            <li>\n               <p>The syntax for the label namespace prefix for a web ACL is the following: </p>\n               <p>\n                  <code>awswaf:<account ID>:webacl:<web ACL name>:</code>\n               </p>\n            </li>\n            <li>\n               <p>When a rule with a label matches a web request, WAF adds the fully qualified label to the request. A fully qualified label is made up of the label namespace from the rule group or web ACL where the rule is defined and the label from the rule, separated by a colon: </p>\n               <p>\n                  <code><label namespace>:<label from rule></code>\n               </p>\n            </li>\n         </ul>"}))
    WebACL.add_member(:custom_response_bodies, Smithy::Schema::Shapes::ShapeRef.new(shape: CustomResponseBodies, location_name: 'CustomResponseBodies', traits: {"smithy.api#documentation" => "<p>A map of custom response keys and content bodies. When you create a rule with a block action, you can send a custom response to the web request. You define these for the web ACL, and then use them in the rules and default actions that you define in the web ACL. </p>\n         <p>For information about customizing web requests and responses, \n           see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/waf-custom-request-response.html\">Customizing web requests and responses in WAF</a> \n    in the <i>WAF Developer Guide</i>. </p>\n         <p>For information about the limits on count and size for custom request and response settings, see <a href=\"https://docs.aws.amazon.com/waf/latest/developerguide/limits.html\">WAF quotas</a> \n     in the <i>WAF Developer Guide</i>. </p>"}))
    WebACL.add_member(:captcha_config, Smithy::Schema::Shapes::ShapeRef.new(shape: CaptchaConfig, location_name: 'CaptchaConfig', traits: {"smithy.api#documentation" => "<p>Specifies how WAF should handle <code>CAPTCHA</code> evaluations for rules that don't have their own <code>CaptchaConfig</code> settings. If you don't specify this, WAF uses its default settings for <code>CaptchaConfig</code>. </p>"}))
    WebACL.add_member(:challenge_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ChallengeConfig, location_name: 'ChallengeConfig', traits: {"smithy.api#documentation" => "<p>Specifies how WAF should handle challenge evaluations for rules that don't have \ntheir own <code>ChallengeConfig</code> settings. If you don't specify this, WAF uses its default settings for <code>ChallengeConfig</code>. </p>"}))
    WebACL.add_member(:token_domains, Smithy::Schema::Shapes::ShapeRef.new(shape: TokenDomains, location_name: 'TokenDomains', traits: {"smithy.api#documentation" => "<p>Specifies the domains that WAF should accept in a web request token. This enables the use of tokens across multiple protected websites. When WAF provides a token, it uses the domain of the Amazon Web Services resource that the web ACL is protecting. If you don't specify a list of token domains, WAF accepts tokens only for the domain of the protected resource. With a token domain list, WAF accepts the resource's host domain plus all domains in the token domain list, including their prefixed subdomains.</p>"}))
    WebACL.add_member(:association_config, Smithy::Schema::Shapes::ShapeRef.new(shape: AssociationConfig, location_name: 'AssociationConfig', traits: {"smithy.api#documentation" => "<p>Specifies custom configurations for the associations between the web ACL and protected resources.  </p>\n         <p>Use this to customize the maximum size of the request body that your protected resources forward to WAF for inspection. You can \n    customize this setting for CloudFront, API Gateway, Amazon Cognito, App Runner, or Verified Access resources. The default setting is 16 KB (16,384 bytes). </p>\n         <note>\n            <p>You are charged additional fees when your protected resources forward body sizes that are larger than the default. For more information, see <a href=\"http://aws.amazon.com/waf/pricing/\">WAF Pricing</a>.</p>\n         </note>\n         <p>For Application Load Balancer and AppSync, the limit is fixed at 8 KB (8,192 bytes).</p>"}))
    WebACL.add_member(:retrofitted_by_firewall_manager, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'RetrofittedByFirewallManager', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Indicates whether this web ACL was created by a customer account and then retrofitted by Firewall Manager. If true, then the web ACL is currently being \n       managed by a Firewall Manager WAF policy, and only Firewall Manager can manage any Firewall Manager rule groups in the web ACL. \n           See also the properties <code>ManagedByFirewallManager</code>, <code>PreProcessFirewallManagerRuleGroups</code>, and <code>PostProcessFirewallManagerRuleGroups</code>. </p>"}))
    WebACL.add_member(:on_source_d_do_s_protection_config, Smithy::Schema::Shapes::ShapeRef.new(shape: OnSourceDDoSProtectionConfig, location_name: 'OnSourceDDoSProtectionConfig', traits: {"smithy.api#documentation" => "<p>Configures the level of DDoS protection that applies to web ACLs associated with Application Load Balancers.</p>"}))
    WebACL.add_member(:application_config, Smithy::Schema::Shapes::ShapeRef.new(shape: ApplicationConfig, location_name: 'ApplicationConfig', traits: {"smithy.api#documentation" => "<p>Returns a list of <code>ApplicationAttribute</code>s.</p>"}))
