    XssMatchStatement.add_member(:field_to_match, Smithy::Schema::Shapes::ShapeRef.new(shape: FieldToMatch, location_name: 'FieldToMatch', traits: {"smithy.api#documentation" => "<p>The part of the web request that you want WAF to inspect. </p>", "smithy.api#required" => {}}))
    XssMatchStatement.add_member(:text_transformations, Smithy::Schema::Shapes::ShapeRef.new(shape: TextTransformations, location_name: 'TextTransformations', traits: {"smithy.api#documentation" => "<p>Text transformations eliminate some of the unusual formatting that attackers use in web requests in an effort to bypass detection. Text transformations are used in rule match statements, to transform the <code>FieldToMatch</code> request component before inspecting it, and they're used in rate-based rule statements, to transform request components before using them as custom aggregation keys. If you specify one or more transformations to apply, WAF performs all transformations on the specified content, starting from the lowest priority setting, and then uses the transformed component contents. </p>", "smithy.api#required" => {}}))
